\begin{definition}
	\label{def:semantic_set_function}
	For a logic $\msf{L}$ and an $\msf{L}$-model $M$, an $(\msf{L},M)$\emph{-pair} $(\msf{SEM}_M,\msf{sem}_M)$ is s.t.:
	\begin{itemize}
		\item $\msf{SEM}_M = \bigcup_{\tau \in \mathcal{T}} \msf{SEM}_M(\tau)$ is a finite set of semantical values, where for all types $\tau,\tau' \in \mathcal{T}$, we have $\msf{SEM}_M(\tau) \cap \msf{SEM}_M(\tau') = \emptyset$. 
		%
		For all $T \subseteq \mathcal{T}$, we let $\msf{SEM}_M(T) := \bigcup_{\tau \in T} \msf{SEM}_M(\tau)$.
		\item $\msf{sem}_M: \msf{Fm}_\msf{L} \rightarrow \msf{SEM}_M$ is the semantic function such that, for all types $\tau \in \mathcal{T}$ and formulas $\varphi \in \msf{Fm}_\msf{L}(\tau)$, we have $\msf{sem}_M(\varphi) \in \msf{SEM}_M(\tau)$.
	\end{itemize} 	
	Unless otherwise stated, an $(\msf{L},M)$-pair $\Theta_M$ refers to the pair $\Theta_M = (\msf{SEM}_M,\msf{sem}_M)$.
\end{definition}

