%For now, given a logic $\msf{L}$ and an $\msf{L}$-model $M$, an $(\msf{L},M)$-pair could be defined arbitrarily and is of no use. Let us define some properties that we will assume that $(\msf{L},M)$-pairs satisfy. First, we say that an $(\msf{L},M)$-pair $\Theta_M$ captures the $\msf{L}$-semantics if the fact that a final $\msf{L}$-formula $\varphi$ is satisfied by the model $M$ depends entirely on the image of $\varphi$ by the function $\msf{sem}$. This is formally defined below.
\begin{definition}[Capturing the $\msf{L}$-semantics]
	\label{def:capturing_semantics}
	Consider a logic $\msf{L}$, an $\msf{L}$-model $M$, and an $(\msf{L},M)$-pair $\Theta_M$. We say that this pair $\Theta_M$ \emph{captures the $\msf{L}$-semantics} if:
	\begin{equation*}
		\forall \tau \in \mathcal{T},\; \forall \varphi,\varphi' \in \msf{Fm}^{\msf{f}}_\msf{L}(\tau):\; \msf{sem}_M(\varphi) = \msf{sem}_M(\varphi') \implies M \models \varphi \text{ iff }M \models \varphi'
	\end{equation*}
	%for all of $\msf{L}$-formulas $\varphi,\varphi' \in \msf{Fm}_\msf{L}$, if $\msf{sem}_M(\varphi) = \msf{sem}_M(\varphi')$, then $M \models \varphi$ if and only if $M \models \varphi'$. 
	In that case, there is some subset $\msf{SAT}_{M} \subseteq \msf{SEM}_M$ such that, for all $\msf{L}$-formulas $\varphi \in \msf{Fm}_\msf{L}^{\msf{f}}$, we have $M \models \varphi$ if and only if we have $\msf{sem}_M(\varphi) \in \msf{SAT}_M$. %Informally, this means that, to know whether an $\msf{L}$-formula is satisfied by $M$, it suffices to consider its image by the function $\msf{sem}_M$.
\end{definition}

\begin{lemma}[Proof~\ref{proof:lem_modal_logic_pair_captures_semantics}]
	\label{lem:modal_logic_pair_captures_semantics}
	For all $K \in \mathcal{K}(\prop,\act)$, the $(\ML(\prop,\act),K)$-pair $\Theta_K$ from Example~\ref{ex:Kripke_structures_SEM} captures the $\ML(\prop,\act)$-semantics.
\end{lemma}

The $(\ML(\prop,\act),K)$-pair $\Theta_K$ from Example~\ref{ex:Kripke_structures_SEM} satisfies a second crucial property, which relates to the fact that the semantic function $\msf{sem}_K$ can be computed in an inductive way. Consider for instance the $\ML(\prop,\act)$-formula $\varphi := \varphi_1 \wedge \varphi_2$. The semantic value $\msf{sem}_K(\varphi) \in \msf{SEM}_K$ is equal to the set of states in $K$ satisfying the formula $\varphi$. By definition of the operator $\wedge$, this exactly corresponds to the set of states in $K$ that satisfy both formulas $\varphi_1$ and $\varphi_2$. This implies that the semantic value $\msf{sem}_K(\varphi)$ can be computed from $\msf{sem}_K(\varphi_1)$ and $\msf{sem}_K(\varphi_2)$, regardless of what the formulas $\varphi_1$ and $\varphi_2$ actually are. In fact, this holds for all $\ML(\prop,\act)$-operators, not only $\wedge$, e.g. the semantic value of the $\ML(\prop,\act)$-formula $\varphi := [a] \varphi'$ is equal to the set of states whose $a$-successors are all in $\msf{sem}_K(\varphi')$. In such a case, we say that this pair $\Theta_K$ satisfies the inductive property. %This is formally defined below% for arbitrary logical formalisms
\begin{definition}
	\label{def:inductive_semantics}
	For a logic $\msf{L}$ and an $\msf{L}$-model $M$, an $(\msf{L},M)$-pair $\Theta_M$ satisfies the \emph{inductive property} if the following holds, for all types $\tau \in \mathcal{T}$. For all $\msf{o} \in \msf{Op}_1(\tau)$, there is a $\Theta_M$-compatible function $\msf{sem}^{\msf{o}}_M: \msf{SEM}_M(T(\msf{o},1)) \rightarrow \msf{SEM}_M(\tau)$ such that, for all $\varphi_1 \in \msf{Fm}_\msf{L}(T(\msf{o},1))$:
	\begin{equation*}
		\msf{sem}_M(\msf{o}(\varphi_1)) = \msf{sem}^{\msf{o}}_M(\msf{sem}_M(\varphi_1)) \in \msf{SEM}_M(\tau)
	\end{equation*}

	In addition, for all $\msf{o} \in \msf{Op}_2(\tau)$, there is a $\Theta_M$-compatible function $\msf{sem}^{\msf{o}}_M: \msf{SEM}_M(T(\msf{o},1)) \times \msf{SEM}_M(T(\msf{o},2)) \rightarrow \msf{SEM}_M(\tau)$ such that, for all $(\varphi_1,\varphi_2) \in \msf{Fm}_\msf{L}(T(\msf{o},1)) \times \msf{Fm}_\msf{L}(T(\msf{o},2))$:
	\begin{equation*}
		\msf{sem}_M(\msf{o}(\varphi_1,\varphi_2)) = \msf{sem}^{\msf{o}}_M(\msf{sem}_M(\varphi_1),\msf{sem}_M(\varphi_2)) \in \msf{SEM}_M(\tau) 
	\end{equation*}
\end{definition}

\begin{lemma}[Proof~\ref{proof:lem_modal_logic_pair_inductive_property}]
	\label{lem:modal_logic_pair_inductive_property}
	For all $K \in \mathcal{K}(\prop,\act)$, the $(\ML(\prop,\act),K)$-pair $\Theta_K$ from Example~\ref{ex:Kripke_structures_SEM} satisfies the inductive property.
\end{lemma}

In the following, we will focus on those classes of $\msf{L}$-models $\mathcal{C}$ for which, for all models $M \in \mathcal{C}$, there are $(\msf{L},M)$-pairs satisfying the two above properties.
\begin{definition}
	\label{def:finitely_inductively_capture_semantics}
	Consider a logic $\msf{L}$ and an $\msf{L}$-model $M$. An $(\msf{L},M)$-pair $\Theta_M$ \emph{inductively capture the $\msf{L}$-semantics} if it captures the $\msf{L}$-semantics and satisfies the inductive property.
