\subsection{A semantic-based meta algorithm}
\label{subsec:algo}

Many enumeration algorithms in the literature use sophisticated techniques to avoid generating syntactically different but semantically identical formulas. However, this proves to be a difficult task as deciding formula equivalence is hard. Thus, these algorithms often resort to using heuristics which do not entirely prevent enumerating semantically identical formulas. 

%This is a very hard thing to do, deciding equivalence is hard. Do not really check in a complete (computationally really expensive), some heuristics, typically cannot prevent enumerating equivalent formulas.

The above proof sketch suggests a meta algorithm that circumvents this difficulty by not enumerating formulas syntactically, but semantically. It consists in enumerating over the possible semantic values of the formulas, instead of the formulas themselves. This meta algorithm is described as Algorithm~\ref{algo:decide_passive_learning} in pseudo-code: in Line 1-7, the set $\msf{SEM}_{\msf{S}}^{\msf{L}}$ is computed via a fixed point computation; in Line 8-10, it is checked that there is some $X \in \msf{SEM}_{\msf{S}}^{\msf{L}}$ such that for all $M \in \mathcal{P}$, we have $X[M] \in \msf{SAT}_M$ and for all $M \in \mathcal{N}$, we have $X[M] \in \msf{SEM}_M \setminus \msf{SAT}_M$. From the proof (sketch), we immediately obtain the following result.

\begin{algorithm}[t]
	\caption{$\msf{PassiveLearning}_{\msf{L},\Theta}$: Decides if an input $\mathcal{C}$-sample $\mathcal{S}$ is $\msf{L}$-separable}
	\label{algo:decide_passive_learning}
	\textbf{Input}: An $\mathcal{C}$-sample $\mathcal{S}$ of models
	\begin{algorithmic}[1]
		\State $\msf{SEM} \gets \emptyset$, $\msf{SEM}' \gets \{ ((\msf{sem}_M(\msf{o}))_{M \in \mathcal{S}},\tau) \mid \tau \in \mathcal{T},\; \msf{o} \in \msf{Op}_0(\tau) \}$
		\While{$\msf{SEM} \neq \msf{SEM}'$}
		\State $\msf{SEM} \gets \msf{SEM}'$
		\For{$\tau \in \mathcal{T},\; \msf{o} \in \msf{Op}_1(\tau),\; \tau_1 \in T(\msf{o},1),\; (X,\tau_1) \in \msf{SEM}'$}
		\State $\msf{SEM}' \gets \msf{SEM}' \cup \{ ((\msf{sem}^{\msf{o}}_M(X[M]),\tau)_{M \in \mathcal{S}},\tau) \}$
		\EndFor 
		\For{$\tau \in \mathcal{T},\; \msf{o} \in \msf{Op}_2(\tau),\; (\tau_1,\tau_2) \in T(\msf{o},1) \times T(\msf{o},2),\; ((X_1,\tau_1),(X_2,\tau_2)) \in (\msf{SEM}')^2$}
		\State $\msf{SEM}' \gets \msf{SEM}' \cup \{ ((\msf{sem}^{\msf{o}}_M(X_1[M],X_2[M]))_{M \in \mathcal{S}},\tau) \}$
		\EndFor 
		\EndWhile
		\For{$\tau \in \mathcal{T}_{\msf{f}},\; (X,\tau) \in \msf{SEM}$}
		\If{$X \in \prod_{M \in \mathcal{P}} \msf{SAT}_M \times \prod_{M \in \mathcal{N}} (\msf{SEM}_M \setminus \msf{SAT}_M)\;$}
		\Return Accept
		\EndIf
		\EndFor 
		\State
		\Return Reject
	\end{algorithmic}
\end{algorithm}

\begin{theorem}[Proof~\ref{proof:thm_size_separation}]
	\label{thm:enumeration_algo}		
	Consider a logic $\msf{L}$, a class of $\msf{L}$-models $\mathcal{C}$ and an $(\msf{L},\mathcal{C})$-pair $\Theta$. Algorithm~\ref{algo:decide_passive_learning} decides the passive learning problem $\msf{PvLn}(\msf{L},\mathcal{C})$. 
\end{theorem}
