			& w \models p & \text{ iff } & p \in w[0] \\
			& w \models \neg \varphi & \text{ iff } & w \not\models \varphi \\
			& w \models \varphi_1 \vee \varphi_2 & \text{ iff } & w \models \varphi_1 \text{ or } w \models \varphi_2\\
			& w \models \varphi_1 \wedge \varphi_2 & \text{ iff } & w \models \varphi_1 \text{ and } w \models \varphi_2
			%& w,i \models_{\msf{pos}} \lY \varphi & \text{ iff } & i > 0,\; \text{and } w,i-1 \models_{\msf{pos}} \varphi \\
