		\begin{align*}
			& w \models \lX \varphi & \text{ iff } & |w| \geq 2 \text{ and }w[1:] \models \varphi \\
			& w \models \lF \varphi & \text{ iff } & \exists j < |w|,\; w[j:] \models \varphi \\
