\begin{definition}[Monotone fragments]
	\label{def:monotone_fragments}
	Consider a non-empty set $\prop$ and let $\msf{L} \in \{\LTL,\ML\}$. An $\msf{L}(\prop)$-fragment $\msf{L}'$ is \emph{monotone} if $\neg \notin \msf{Op}'$, and $|\{ \vee,\wedge\} \cap \msf{Op}'| \leq 1$.
