\section{Proofs on modal logic}
\subsection{Proof of Lemma~\ref{lem:modal_logic_pair_captures_semantics}}
%\texorpdfstring{Proof of Lemma~\ref{lem:modal_logic_pair_captures_semantics}}{Proof of Lemma~\ref{lem:modal_logic_pair_captures_semantics}}
\label{proof:lem_modal_logic_pair_captures_semantics}
\begin{proof}
	Consider a Kripke structure $K \in \mathcal{K}(\prop,\act)$. For all $\ML(\prop,\act)$-formulas $\varphi,\varphi'$, if $\msf{sem}_K(\varphi) = \msf{sem}_K(\varphi')$, then:
	\begin{align*}
		K \models \varphi & \Longleftrightarrow \forall q \in I,\; q \models \varphi \Longleftrightarrow \forall q \in I,\; q \in \msf{sem}_K(\varphi) = \msf{sem}_K(\varphi') \\
		& \Longleftrightarrow \forall q \in I,\; q \models \varphi' \Longleftrightarrow K \models \varphi'
	\end{align*}
	In this case, we have $\msf{SAT}_{K} := \{ S \in 2^Q \mid I \subseteq S \}$.
\end{proof}


\subsection{Proof of Lemma~\ref{lem:modal_logic_pair_inductive_property}}
\label{proof:lem_modal_logic_pair_inductive_property}
\begin{proof}
	Consider a Kripke structure $K \in \mathcal{K}(\prop,\act)$. Let us define $\Theta_K$-compatible functions for all operators $\msf{o} \in \msf{Op}_1 \cup \msf{Op}_2$. For all $S,S_1,S_2 \in \msf{SEM}_K = 2^Q$, we let:
	\begin{itemize}
		\item $\msf{sem}_K^{\neg}(S) := Q \setminus S \in \msf{SEM}_K$;
		\item for all $a\in \act$ and $k \in \N$, $\msf{sem}_K^{\langle a \rangle^{\geq k}}(S) := \{q \in Q \mid \delta(q,a) \cap S \geq k \}$
		\item for all $a\in \act$, $\msf{sem}_K^{[a]}(S) := \{q \in Q \mid \delta(q,a) \subseteq S \}$
		\item $\msf{sem}_K^{\wedge}(S_1,S_2) := S_1 \cap S_2 \in \msf{SEM}_K$;
		\item $\msf{sem}_K^{\lor}(S_1,S_2) := S_1 \cup S_2 \in \msf{SEM}_K$.
	\end{itemize}
	It is straightforward to check that, with these definitions, all of the above functions do correspond to $\Theta_K$-compatible functions. Let us for instance consider the case of the operator $\wedge \in \msf{Op}_2$. For all $\varphi_1,\varphi_2 \in \msf{Fm}_{\ML(\prop,\act)} \times \msf{Fm}_{\ML(\prop,\act)}$, we have:
	\begin{align*}
		\msf{sem}_K^{\wedge}(\msf{sem}_K(\varphi_1),\msf{sem}_K(\varphi_2)) & = \msf{sem}_K(\varphi_1) \cap \msf{sem}_K(\varphi_2) \\
		& = \{q \in Q \mid q \models \varphi_1 \} \cap \{q \in Q \mid q \models \varphi_2 \} \\
		& = \{ q \in Q \mid q \models \varphi_1 \text{ and }q \models \varphi_2 \} \\
		& = \{ q \in Q \mid q \models \varphi_1 \wedge \varphi_2 \} \\
		& = \msf{sem}_K(\varphi_1 \wedge \varphi_2)
	\end{align*}
	This is similar with the $[a]$ for some $a \in \act$:
	For all $\varphi' \in \msf{Fm}_{\ML(\prop,\act)}$, we have:
	\begin{align*}
		\msf{sem}_K^{[a]}(\msf{sem}_K(\varphi')) & = \{q \in Q \mid \delta(q,a) \subseteq \msf{sem}_K(\varphi') \} \\
		& = \{ q \in Q \mid \delta(q,a) \subseteq \{ q' \in Q \mid q' \models \varphi' \} \} \\
		& = \msf{sem}_K([a] \; \varphi')
	\end{align*}

	Since there are $\Theta_K$-compatible functions for all operators $\msf{o} \in \msf{Op}_1 \cup \msf{Op}_2$, it follows that the $(\ML(\prop,\act),K)$-pair $\Theta_K$ inductively captures the $\ML(\prop,\act)$-semantics. 

	%Consider now Assumptions~\ref{assump:for_complexity}. Clearly, all of the sets $\msf{SEM}_K(\top),\msf{SEM}_K(\bot),\msf{SEM}_K(p)$ (for all propositions $p \in \prop$) and all of the above functions can be computed in time polynomial in $|M|$. Furthermore, checking that some $S \in \msf{SEM}_K$ is in the set $\msf{SAT}_K$ can also be done in polynomial time. In addition, we have $|\msf{SEM}_K| = 2^{|Q|} \leq 2^{|M|}$. Thus, the $(\ML(\prop,\act),K)$-pair $\Theta_K$ satisfies Assumptions~\ref{assump:for_complexity}.
\end{proof}

