\section{Proof of Theorems~\ref{thm:size_separation} and~\ref{thm:enumeration_algo}}
\label{proof:thm_size_separation}

We start with the proof of Theorem~\ref{thm:size_separation}, the proof of Theorem~\ref{thm:enumeration_algo} that will follow uses some of statements used to prove Theorem~\ref{thm:size_separation}. 

\subsection{Proof of Theorem~\ref{thm:size_separation}}
We are actually going to prove a (slightly) stronger statement than Theorem~\ref{thm:size_separation} as we consider a (slightly) more general setting than the passive learning problem. This is captured by the notion of learning property, defined below.
\begin{definition}
	\label{def:learning_prop}
	Consider a logic $\msf{L}$ and a finite set of $\msf{L}$-models $\mathcal{S}$. An $(\msf{L},\mathcal{S})$-learning property $\mathcal{R} \subseteq \msf{Fm}_{\msf{L}}^{\msf{f}}$ is a subset of final $\msf{L}$-formulas such that, letting: 
	\begin{equation*}
		\mathcal{R}_{\mathcal{S}} := \{ \{ M \in \mathcal{S} \mid M \models \varphi \} \mid \varphi \in \mathcal{R} \}
	\end{equation*}
	we have:
	\begin{equation*}
		\forall \varphi \in \msf{Fm}_{\msf{L}}^{\msf{f}}:\; \{ M \in \mathcal{S} \mid M \models \varphi \} \in 	\mathcal{R}_{\mathcal{S}} \Longleftrightarrow \varphi \in \mathcal{R}
	\end{equation*}
	In other words, whether or not a final $\msf{L}$-formula $\varphi$ belongs to $\mathcal{R}$ entirely depends on the set of models in $\mathcal{S}$ satisfying $\varphi$.
\end{definition}

Let us now state the proposition that generalizes Theorem~\ref{thm:size_separation} to the more general case of learning properties.
\begin{proposition}
	\label{prop:size_separation}
	Consider a logic $\msf{L}$, a fragment $\msf{L}'$ of the logic $\msf{L}$, a class of $\msf{L}$-models $\mathcal{C}$ and an $(\msf{L},\mathcal{C})$-pair $\Theta$. Let $\mathcal{S} \subseteq \mathcal{C}$ be a finite set of $\msf{L}$-models, and $\mathcal{R} \subseteq \msf{Fm}_{\msf{L}}^{\msf{f}}$ be an $(\msf{L},\mathcal{S})$-learning property. If there is an $\msf{L}'$-formula in $\mathcal{R}$, then there is one of size at most $n^{\mathcal{S}}_{\Theta} = \sum_{\tau \in \mathcal{T}} \prod_{M \in \mathcal{S}} |\msf{SEM}_M(\tau)|$.
\end{proposition}

The remainder of this subsection is devoted to the of Proposition~\ref{prop:size_separation}. Therefore, we fix a logic $\msf{L}$, a fragments $\msf{L}'$ of the logic $\msf{L}$, a class of $\msf{L}$-models $\mathcal{C}$, an $(\msf{L},\mathcal{C})$-pair $\Theta$, a finite set of $\msf{L}$-models $\mathcal{S} \subseteq \mathcal{C}$, and an $(\msf{L},\mathcal{S})$-learning property $\mathcal{R} \subseteq \msf{Fm}_{\msf{L}}^{\msf{f}}$ for all of this subsection. %In the following, for all $\msf{L}$-formulas $\varphi$, we let $\tau_\varphi \in \mathcal{T}$ denote the type of the formula $\varphi$.

Let us first define iteratively sets of tuples of semantic sets. This is done formally below.
\begin{definition}
	\label{def:inductive_def_semantics_sets}
	We define by induction the sets $(\msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}(\tau))_{i \in \N, \tau \in \mathcal{T}}$, as follows:
	\begin{itemize}
		\item For all $\tau \in \mathcal{T}$, we define:
		\begin{align*}
			\msf{SEM}_{\mathcal{S},\Theta,0}^{\msf{L}'}(\tau) & := \{ (\msf{sem}_M(\msf{o}))_{M \in \mathcal{S}} \mid \msf{o} \in \msf{Op}_0'(\tau) \} \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)
		\end{align*}
		%and, for all $\msf{z} := (\msf{cx}_M,\msf{S}_M)_{M \in \mathcal{S}} \in \msf{SEM}_{\mathcal{S},0}^{\msf{L}'}(\tau)$, we let:
		%\begin{equation*}
		%	f_{\mathcal{S}}^{\msf{L}'}(\msf{z}) := \{ \varphi \in \msf{Op}_0 \cap \msf{Fm}_{\msf{L}'}(\tau) \mid \forall M \in \mathcal{S},\; \msf{S}_M = \msf{sem}^M_\tau(\msf{cx}_M,\varphi) \}
		%\end{equation*}
		\item For all $i \geq 0$, for all $\tau \in \mathcal{T}$, we let:
		\begin{align*}
			\msf{Seq}_{\mathcal{S},\Theta,i+1}^{\msf{L}'}(\tau) := \msf{Seq}_{\mathcal{S},\Theta,i}^{\msf{L}'}(\tau) \cup  \msf{Seq}_{\mathcal{S},\Theta,i+1}^{\msf{L}',1}(\tau) \cup \msf{Seq}_{\mathcal{S},\Theta,i+1}^{\msf{L}',2}(\tau)
		\end{align*}
		with 
		\begin{align*}
			\msf{Seq}_{\mathcal{S},\Theta,i+1}^{\msf{L}',1}(\tau) & := \{ (\msf{sem}_{M}^{\msf{o}}(\msf{X}[M]))_{M \in \mathcal{S}} \mid \msf{o} \in \msf{Op}_1'(\tau),\; \msf{X} \in \msf{SEM}_{\mathcal{S},i}^{\msf{L}'}(T(\msf{o},1))  \} \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)
		\end{align*}
		and
		\begin{align*}
			\msf{Seq}_{\mathcal{S},\Theta,i+1}^{\msf{L}',2}(\tau) & := \{ (\msf{sem}_{M}^{\msf{o}}(\msf{X}^1[M],\msf{X}^2[M]))_{M \in \mathcal{S}} \mid \msf{o} \in \msf{Op}_2'(\tau),\; \\ 	& \phantom{aaaa} (\msf{X}^1,\msf{X}^2) \in \msf{SEM}_{\mathcal{S},i}^{\msf{L}'}(T(\msf{o},1)) \times \msf{SEM}_{\mathcal{S},i}^{\msf{L}'}(T(\msf{o},2)) \} \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)
		\end{align*}
	\end{itemize}
	where, for all $i \in \N$ and $T \subseteq \mathcal{T}$, $\msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}(T)$ denotes the set $\bigcup_{\tau \in T} \msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}(\tau)$. Then:
	\begin{itemize}
		\item for all $\tau \in \mathcal{T}$, we let  $\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}(\tau) := \bigcup_{n \in \N} \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(\tau) \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)$;
		\item for all $n \in \mathbb{N}$, we let $\msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'} := \bigcup_{\tau \in \mathcal{T}} \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(\tau) \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M$;
		\item $\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} := \bigcup_{\tau \in \mathcal{T}} \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}(\tau) = \bigcup_{n \in \N} \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'} \subseteq \bigcup_{\tau \in \mathcal{T}} \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)$. 
	\end{itemize}
\end{definition}

On the other hand, let us define the set of tuples of semantic sets that any $\msf{L}'$-formula can be mapped to by semantic functions.
\begin{definition}
	We let $\msf{sem}_\Theta: \msf{Fm}_{\msf{L}'} \to \prod_{M \in \mathcal{S}} \msf{SEM}_M$ be such that, for all $\varphi \in \msf{Fm}_{\msf{L}'}$, $\msf{sem}_\Theta(\varphi) := (\msf{sem}_M(\varphi))_{M \in \mathcal{S}} \in \prod_{M \in \mathcal{S}} \msf{SEM}_M$. Then, we let:	
	\begin{equation*}
		\msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'} := \msf{sem}_\Theta[\msf{Fm}_{\msf{L}'}] \subseteq \prod_{M \in \mathcal{S}} \msf{SEM}_M
	\end{equation*}
\end{definition}

We claim that these two sets $\msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'}$ and $\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$ are actually equal, as stated in the two lemmas below.
\begin{lemma}
	\label{lem:allsat_achieved_by_computation}
	We have: $\msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'} \subseteq \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$.
\end{lemma}
\begin{proof}
	Let us show by induction on $\msf{L}'$-formulas $\varphi \in \msf{Fm}_{\msf{L}'}$ the property $\mathcal{P}(\varphi)$: $\msf{sem}_\Theta(\varphi) \in \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. Consider first any $\msf{L}'$-formula $\varphi \in \msf{Op}_0 \cap \msf{Fm}_{\msf{L}'}$. By definition, we have $\msf{sem}_\Theta(\varphi) = (\msf{SEM}_M(\varphi))_{M \in \mathcal{S}} \in \msf{SEM}_{\mathcal{S},\Theta,0}^{\msf{L}'} \subseteq \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. Hence, $\mathcal{P}(\varphi)$ holds. 

	Now, let $\tau \in \mathcal{T}$ be a type and consider an operator $\msf{o} \in \msf{Op}_2$ such that $\tau_\msf{o} = \tau$. Assume that the properties $\mathcal{P}(\varphi_1),\mathcal{P}(\varphi_2)$ hold for two $\msf{L}'$-formulas $(\varphi_1,\varphi_2) \in \msf{Fm}_{\msf{L}'}(T(\msf{o},1)) \times \msf{Fm}_{\msf{L}'}(T(\msf{o},2))$ such that $\varphi := \msf{o}(\varphi_1,\varphi_2) \in \msf{Fm}_{\msf{L}'}(\tau)$. By $\mathcal{P}(\varphi_1)$ and $\mathcal{P}(\varphi_2)$, we have $\msf{sem}_\Theta(\varphi_1) \in \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$ and $\msf{sem}_\Theta(\varphi_2) \in \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. Thus, there is $n \in \mathbb{N}$ such that $(\msf{sem}_\Theta(\varphi_1),\msf{sem}_\Theta(\varphi_2)) \in \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(T(\msf{o},1)) \times \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(T(\msf{o},2))$, with $\msf{o}(\varphi_1,\varphi_2) \in \msf{Fm}_{\msf{L}'}(\tau)$. Thus, we have:
	\begin{align*}
		\msf{sem}_{\Theta}(\varphi) & = (\msf{sem}_M(\varphi))_{M \in \mathcal{S}} \\
		& = (\msf{sem}^{\msf{o}}_{M}(\msf{sem}_M(\varphi_1),\msf{sem}_M(\varphi_2)))_{M \in \mathcal{S}} \in \msf{SEM}_{\mathcal{S},\Theta,n+1}^{\msf{L}'}(\tau) \subseteq \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}
	\end{align*}

	Thus, $\mathcal{P}(\varphi)$ holds. Similar arguments also apply to arity-1 operators $\msf{o} \in \msf{Op}_1$. In fact, $\mathcal{P}(\varphi)$ holds for all $\msf{L}'$-formulas $\varphi \in \msf{Fm}_{\msf{L}'}$. Hence, $\msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'} \subseteq \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$.
\end{proof}

\begin{lemma}
	\label{lem:achieved_sat_injective_function}
	There is a function $\varphi_\Theta: \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} \rightarrow \msf{Fm}_{\msf{L}'}$ such that, for all $X \in \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$:
	\begin{enumerate}
		\item $\msf{sem}_\Theta(\varphi_\Theta(X)) = X$; and
		\item for all $\varphi \in \msf{Sub}(\varphi_\Theta(X))$, we have: $\varphi = \varphi_\Theta(\msf{sem}_\Theta(\varphi))$.
	\end{enumerate}
\end{lemma}
\begin{proof}
	We define the function $\varphi_\Theta: \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} \rightarrow \msf{Fm}_{\msf{L}'}$, with $\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} = \bigcup_{i \in \N} \msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}$, by induction on $i \in \mathbb{N}$. First, consider some $X \in \msf{SEM}_{\mathcal{S},\Theta,0}^{\msf{L}'}$. We let $\varphi_{\Theta}(X) \in \msf{Op}_0'$ be some arity-0 operator such that $\msf{sem}_\Theta(\varphi_{\Theta}(X)) = (\msf{sem}_M(\varphi_{\Theta}(X)))_{M \in \mathcal{S}} = X$. Note that this is indeed possible by definition of $\msf{SEM}_{\mathcal{S},\Theta,0}^{\msf{L}'}$. This satisfies both conditions (1),(2) above by definition.

	Now, assume that the function $\varphi_\Theta$ is already defined on $\bigcup_{i \leq n} \msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}$ for some $n \in \mathbb{N}$, and assume that it satisfies both conditions (1),(2) above on this set. In particular, this implies that, for all $X \in \bigcup_{i \leq n} \msf{SEM}_{\mathcal{S},\Theta,i}^{\msf{L}'}$ and for all $\varphi \in \msf{Sub}(\varphi_\Theta(X))$, the formula $\varphi_\Theta(\msf{sem}_\Theta(\varphi)) \in \msf{Fm}_{\msf{L}'}$ is well-defined.

	Consider now any $X \in \msf{SEM}_{\mathcal{S},\Theta,n+1}^{\msf{L}'}$ on which the function $\varphi_\Theta$ is not already defined. Assume that $X \in \msf{SEM}_{\mathcal{S},\Theta,n+1}^{\msf{L}',2}(\tau)$ for some type $\tau \in \mathcal{T}$. (The case $X \in \msf{SEM}_{\mathcal{S},\Theta,n+1}^{\msf{L}',1}(\tau)$ is similar.) By definition, this implies that there is some arity-2 operator $\msf{o} \in \msf{Op}_2'$ and $X^1 = (X^1_M)_{M \in \mathcal{S}} \in \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(T(\msf{o},1))$ and $X^2 = (X^2_M)_{M \in \mathcal{S}} \in \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}'}(T(\msf{o},2))$ such that $X = (\msf{sem}^{\msf{o}}_{M}(X^1_M,X^2_M))_{M \in \mathcal{S}}$. By assumption, the function $\varphi_\Theta$ is defined on $X^1$ and $X^2$. Since we have $\msf{sem}_\Theta(\varphi_\Theta(X^1)) = X^1 \in \msf{SEM}_{\mathcal{S},\Theta,n}^{\msf{L}',n}(T(\msf{o},1))$, it follows that $\varphi_\Theta(X^1) \in \msf{Fm}_{\msf{L}'}(T(\msf{o},1))$. Similarly, we have $\varphi_\Theta(X^2) \in \msf{Fm}_{\msf{L}'}(T(\msf{o},2))$. Hence, $\varphi := \msf{o}(\varphi_\Theta(X^1),\varphi_\Theta(X^2))$ is an $\msf{L}'$-formula. Thus, we let $\varphi_\Theta(X) := \varphi$. Consider any $M \in \mathcal{S}$. Since $\varphi_\Theta$ satisfies condition (1) on $X^1$ and $X^2$, we have $\msf{sem}_M(\varphi_{\Theta}(X^1)) = X^1_M$ and $\msf{sem}_M(\varphi_{\Theta}(X^2)) = X^2_M$. Furthermore, since the function $\msf{sem}^{\msf{o}}_{M}$ is $\Theta_M$-compatible, we have $\msf{sem}_M(\msf{o}(\varphi_\Theta(X^1),\varphi_\Theta(X^2))) = \msf{sem}^{\msf{o}}_{M}(\msf{sem}_M(\varphi_\Theta(X^1)),\msf{sem}_M(\varphi_\Theta(X^2)))$ (recall Definition~\ref{def:inductive_semantics}). Thus, we have:
	\begin{align*}
		\msf{sem}_M(\varphi_\Theta(X)) & = \msf{sem}_M(\msf{o}(\varphi_\Theta(X^1),\varphi_\Theta(X^2))) \\
		& = \msf{sem}^{\msf{o}}_{M}(\msf{sem}_M(\varphi_\Theta(X^1)),\msf{sem}_M(\varphi_\Theta(X^2))) \\
		& = \msf{sem}^{\msf{o}}_{M}(X^1_M,X^2_M) \\
		& = X_M
	\end{align*}
	Therefore, we have $\msf{sem}_\Theta(\varphi_\Theta(X)) = X$. Thus condition (1) holds on $X$. Consider now any $\psi \in \msf{Sub}(\varphi_\Theta(X))$. If $\psi \in \msf{Sub}(\varphi_\Theta(X^1)) \cup  \msf{Sub}(\varphi_\Theta(X^2))$, then by assumption we have $\psi = \varphi_\Theta(\msf{sem}_\Theta(\psi))$. Otherwise, $\psi = \varphi_\Theta(X) = \varphi_\Theta(\msf{sem}_\Theta(\varphi_\Theta(X))) = \varphi_\Theta(\msf{sem}_\Theta(\psi))$. Thus condition (2) holds on $X$ as well. In fact, both of these conditions hold on $X$. We can then define $\varphi_\Theta$ on all of $\msf{SEM}_{\mathcal{S},\Theta,n+1}^{\msf{L}'}$. That way, we can define $\varphi_\Theta: \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} \rightarrow \msf{Fm}_{\msf{L}'}$ while satisfying both conditions (1) and (2).
\end{proof}

The proof of Proposition~\ref{prop:size_separation} now follows.
\begin{proof}
	Assume that $\mathcal{R} \cap \msf{Fm}_{\msf{L}'}^{\msf{f}} \neq \emptyset$. Consider then any $\varphi \in \mathcal{R} \cap \msf{Fm}_{\msf{L}'}$. Let $X = (X_M)_{M \in \mathcal{S}} := \msf{sem}_\Theta(\varphi) \in \msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. By Lemma~\ref{lem:allsat_achieved_by_computation}, we have $\msf{AllSEM}_{\mathcal{S},\Theta}^{\msf{L}'} \subseteq \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. Thus, $X \in \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$. Consider the function $\varphi_\Theta: \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'} \rightarrow \msf{Fm}_{\msf{L}'}$ from Lemma~\ref{lem:achieved_sat_injective_function}. Let $\psi := \varphi_\Theta(X) \in \msf{Fm}_{\msf{L}'}$. We claim that $\psi$ is in $\mathcal{R}$ and of size at most $n_\Theta^{\mathcal{S}}$.

	Consider any $M \in \mathcal{S}$. Since $\varphi_\Theta$ satisfies condition (1) of Lemma~\ref{lem:achieved_sat_injective_function}, we have $\msf{sem}_M(\psi) = X_M = \msf{sem}_M(\varphi) \in \msf{SEM}_M$. This implies that $\psi$ and $\varphi$ are of the same type, and thus $\psi \in \msf{Fm}_{\msf{L}'}^{\msf{f}}$. Furthermore, because the $(\msf{L},M)$-pair $\Theta_M$ captures the $\msf{L}$-semantics (recall Definition~\ref{def:capturing_semantics}), it follows that $M \models \psi \Longleftrightarrow M \models \varphi$. Thus, we have $\{ M \in \mathcal{S} \mid M \models \psi \} = \{ M \in \mathcal{S} \mid M \models \varphi \} \in \mathcal{R}_{\mathcal{S}}$. Thus, we have $\psi \in \mathcal{R}$.

	Furthermore, the function $\msf{sem}_\Theta: \msf{Sub}(\psi) \to \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}$ is injective. Indeed, for all $\varphi,\varphi' \in \msf{Sub}(\psi)$, if $\msf{sem}_\Theta(\varphi) = \msf{sem}_\Theta(\varphi')$, since the function $\varphi_\Theta$ satisfies condition (2) of Lemma~\ref{lem:achieved_sat_injective_function}, it follows that $\varphi = \varphi_\Theta(\msf{sem}_\Theta(\varphi)) = \varphi_\Theta(\msf{sem}_\Theta(\varphi')) = \varphi'$. Therefore, we have $|\msf{Sub}(\psi)| \leq |\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}|$. Hence:
	\begin{equation*}
		\msf{sz}(\psi) \leq |\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}| = |\bigcup_{\tau \in \mathcal{T}} \msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}'}(\tau)|\leq |\bigcup_{\tau \in \mathcal{T}} \prod_{M \in \mathcal{S}} \msf{SEM}_M(\tau)| \leq \sum_{\tau \in \mathcal{T}} \prod_{M \in \mathcal{S}} |\msf{SEM}_M(\tau)|
	\end{equation*}
\end{proof}

The proof of Theorem~\ref{thm:size_separation} is now direct.
\begin{proof}
	Consider a $\mathcal{C}$-sample $\mathcal{S} = (\mathcal{P},\mathcal{N})$. Let $\mathcal{R}$ denote the $(\msf{L},\mathcal{S})$-learning property for which $\mathcal{R}_{\mathcal{S}} = \{\mathcal{P}\}$. (Here, $\mathcal{S}$ is seen as the set $\mathcal{S} = \mathcal{P} \cup \mathcal{N}$). Clearly, for all fragments $\msf{L}'$ of the logic $\msf{L}$, a final $\msf{L}'$-formula $\varphi$ is $\mathcal{S}$-separating if and only if $\varphi \in \mathcal{R}$. We can therefore apply Proposition~\ref{prop:size_separation}.
\end{proof}

