\section{Proof of Proposition~\ref{prop:modal_logic_complexity}}
\label{proof:prop_modal_logic_complexity}
\begin{proof}
	Consider a $\mathcal{K}(\prop,\act)$-sample $\mathcal{S}$ of Kripke structures.

	First of all, there are infinitely many $\ML$-operators of arity 2, since we have $\msf{Op}_{\langle \cdot \rangle} := \{ \langle a \rangle^{\geq k} \mid a \in \act, k \in \N \} \subseteq \msf{Op}_2$. We let $\msf{RelOp}_{\langle \cdot \rangle}(\mathcal{S}) := \{ \langle a \rangle^{\geq k} \mid a \in \act, k \leq \max_{K \in \mathcal{S}} |Q_K| \} \subseteq \msf{Op}_{\langle \cdot \rangle}$ be a set of \emph{relevant operators} of arity 2. This set satisfies the following property: for all $\msf{o} \in \msf{Op}_{\langle \cdot \rangle}$, there is a relevant operator $\msf{o}' \in \msf{RelOp}_{\langle \cdot \rangle}(\mathcal{S})$ such that, for all $K \in \mathcal{S}$, the $\Theta_K$-compatible functions $\msf{sem}_K^\msf{o}$ and $\msf{sem}_K^{\msf{o}'}$ are equal.

	Then, we let $\msf{RelOp}_2(\mathcal{S}) := (\msf{Op}_2 \setminus \msf{Op}_{\langle \cdot \rangle}) \cup \msf{RelOp}_{\langle \cdot \rangle}(\mathcal{S})$. Note that we have $|\msf{RelOp}(\mathcal{S})|$ polynomial in $n = \Sigma_{K \in \mathcal{S}} |Q_K|$. Now, we have that looping over the operators in $\msf{RelOp}_2(\mathcal{S})$ instead of $\msf{Op}_2$ (in Line 6 of Algorithm~\ref{algo:decide_passive_learning}) does not change the output of the algorithm (by the above property satisfied by the set of relevant operators $\msf{RelOp}_{\langle \cdot \rangle}(\mathcal{S})$).

	Let us now consider the complexity of the algorithm %the instantiation of Algorithm~\ref{algo:decide_passive_learning} to the case of modal logic formulas evaluated on Kripke structures 
	when looping over $\msf{RelOp}_2(\mathcal{S})$ in Line 6 instead of $\msf{Op}_2$:
	\begin{itemize}
		\item The while loop is exited after at most $|\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}}| \leq |\prod_{M \in \mathcal{S}} \msf{SAT}_M| = 2^n$ steps. Furthermore, as each step of this while loop, the algorithm runs through all operators in $\msf{Op}_1 \cup \msf{RelOp}_2$, and (pairs of) elements of the set $\msf{SEM}$, and applies the $\Theta_K$-functions $\msf{sat}_K$, for all models $K \in \mathcal{S}$. These functions can all be computed in time polynomial in $|Q_K|$ (as can be seen in the proof in Appendix~\ref{proof:lem_modal_logic_pair_inductive_property} of Lemma~\ref{lem:modal_logic_pair_inductive_property}). 
		In addition, the comparison of the sets $\msf{SEM}$ and $\msf{SEM}'$, of size at most $2^n$, can be done in time $2^{O(n)}$. Therefore, running Lines 1-7 can be done in time $2^{O(n)}$.
		\item As for Line 8-10, it amounts to running through the set $\msf{SEM}$, of size at most $|\msf{SEM}_{\mathcal{S},\Theta}^{\msf{L}}| \leq 2^n$. For each of these elements $X \in \msf{SEM}$, for all Kripke structures $K \in \mathcal{S}$, it is checked whether $X_K \in \msf{SAT}_K$, which can be done in time polynomial in $|Q_K|$ (as this amounts to checking a set inclusion). Thus, executing Lines 8-10 can also be done in time $2^{O(n)}$. 
	\end{itemize}
\end{proof}


\section{Another definition of what it means for a pair to satisfy the inductive property}
We make a remark below that gives a reformulation of what it means for a pair to satisfy the inductive property. 
\begin{remark}
	\label{rmk:sufficient_condition}
	Consider a logic $\msf{L}$ and an $\msf{L}$-model $M$. An $(\msf{L},M)$-pair $\Theta_M$ satisfies the inductive property if and only if the following holds, for all types $\tau$. 
	\begin{itemize}
		\item For all $\msf{o} \in \msf{Op}_1(\tau)$, we have:
		\begin{equation*}
			\forall \varphi,\varphi' \in \msf{Fm}_{\msf{L}}(T(\msf{o},1)):\; \msf{sem}_M(\varphi) = \msf{sem}_M(\varphi') \implies \msf{sem}_M(\msf{o}(\varphi)) = \msf{sem}_M(\msf{o}(\varphi'))
		\end{equation*}
		\item For all $\msf{o} \in \msf{Op}_2(\tau)$, we have:
		\begin{align*}
			& \forall \varphi,\varphi' \in \msf{Fm}_{\msf{L}}(T(\msf{o},1)),\; \forall \psi,\psi' \in \msf{Fm}_{\msf{L}}(T(\msf{o},2)) :\; \\
			& (\msf{sem}_M(\varphi),\msf{sem}_M(\psi)) = (\msf{sem}_M(\varphi'),\msf{sem}_M(\psi')) \implies \msf{sem}_M(\msf{o}(\varphi,\psi)) = \msf{sem}_M(\msf{o}(\varphi',\psi'))
		\end{align*}
	\end{itemize}
\end{remark}

\section{Proof of Corollaries~\ref{coro:ltl_logic}}
\label{proof:corollary_ltl}
\begin{proof}
	Let us apply Theorem~\ref{thm:size_separation}. Consider an infinite word $w = u \cdot v^\omega \in \mathcal{W}(\prop)$, and let $n := ||w||-1$. We let $\msf{Pos}(w) := \Interval{0,n}$, and for all $i \in \msf{Pos}(w)$, we let:
	\begin{itemize}
		\item $\msf{Succ}(i) := \{i+1\}$ if $i < n$; otherwise $\msf{Succ}(i) := \emptyset$ if $|w|-1 = |u|-1 = i$; otherwise $\msf{Succ}(i) := \{|u|\}$. This ensures that, for all $j \in \msf{Succ}(i)$: $w[i :] = w[i] \cdot w[j:] \in (2^{\prop})^{\omega}$.
		\item $\msf{After}(i) := \Interval{\min(i,|u|),n}$. This ensures that: $\{ w[j:] \mid i \leq j \} = \{ w[j:] \mid j \in \msf{After}(i) \}$ (in both cases where $w$ is finite or infinite).
		\item For all $k \in \msf{After}(i)$: $\msf{Between}(i,k) := \Interval{i,k-1}$ if $i \leq k$, and $\msf{Between}(i,k) := \Interval{i,n} \cup \Interval{|u|,k-1}$ otherwise (note that the latter case cannot occur if $w$ is finite). This ensures that, letting $\msf{Between}(i,k) = \{ i_0 < i_1 < \ldots < i_x \}$, we have $w[i:] = w[i_0] \cdot w[i_1] \cdots w[i_x] \cdot w[k:]$.
	\end{itemize}

	Now, we let $\msf{SEM}_w := 2^{\msf{Pos}(w)}$, and for all $\LTL(\prop)$-formulas $\varphi \in \msf{Fm}_{\LTL(\prop)}$:
	\begin{equation*}
		\msf{sem}_w(\varphi) := \{ i \in \msf{Pos}(w) \mid w[i:] \models \varphi \}
	\end{equation*}
	Let us show that the $(\LTL(\prop),w)$-pair $(\msf{SEM}_w,\msf{sem}_w)$ inductively captures the $\LTL(\prop)$-semantics. It clearly captures the $\LTL(\prop)$-semantics since we have $w  = w[0:]$. Let us now focus on the inductive property. For all $\LTL(\prop)$-formulas $\varphi \in \msf{Fm}_{\LTL(\prop)}$, we have:
	\begin{itemize}
		\item $\msf{sem}_w(\neg \varphi) = \msf{Pos}(w) \setminus \msf{sem}_w(\varphi)$;
		\item $\msf{sem}_w(\lX \varphi) = \{ i \in \msf{Pos}(w) \mid \msf{Succ}(i) \cap \msf{sem}_w(\varphi) \neq  \emptyset \}$;
		\item $\msf{sem}_w(\lF \varphi) = \{ i \in \msf{Pos}(w) \mid \msf{After}(i) \cap \msf{sem}_w(\varphi) \neq \emptyset \}$;
		\item $\msf{sem}_w(\lG \varphi) = \{ i \in \msf{Pos}(w) \mid \msf{After}(i) \subseteq \msf{sem}_w(\varphi) \}$.
	\end{itemize}
	Thus, for all $\msf{o} \in \msf{Op}_1$, for all $(\varphi,\varphi') \in (\msf{Fm}_{\LTL(\prop)})^2$, we have:
	\begin{equation*}
		\msf{sem}_w(\varphi) = \msf{sem}_w(\varphi') \implies \msf{sem}_w(\msf{o} \; \varphi) = \msf{sem}_w(\msf{o} \; \varphi')
	\end{equation*}

	Furthermore, for all pairs of $\LTL(\prop)$-formulas $(\varphi_1,\varphi_2) \in (\msf{Fm}_{\LTL(\prop)})^2$, we have:
	\begin{itemize}
		\item $\msf{sem}_w(\varphi_1 \wedge \varphi_2) =  \msf{sem}_w(\varphi_1) \cap \msf{sem}_w(\varphi_2)$;
		\item $\msf{sem}_w(\varphi_1 \vee \varphi_2) =  \msf{sem}_w(\varphi_1) \cup \msf{sem}_w(\varphi_2)$;
		\item $\msf{sem}_w(\varphi_1 \lU \varphi_2) = \{ i \in \msf{Pos}(w) \mid \exists k \in \msf{After}(i) \cap \msf{sem}_{w}(\varphi_2):\; \msf{Between}(i,k) \subseteq  \msf{sem}_{w}(\varphi_1) \}$.
	\end{itemize}
	Thus, for all $\msf{o} \in \msf{Op}_2$, for all $(\varphi_1,\varphi_1',\varphi_2,\varphi_2') \in (\msf{Fm}_{\LTL(\prop)})^4$, we have:
	\begin{equation*}
		(\msf{sem}_w(\varphi_1),\msf{sem}_w(\varphi_2)) = (\msf{sem}_w(\varphi_1'),\msf{sem}_w(\varphi_2')) \implies \msf{sem}_w(\varphi_1 \; \msf{o} \; \varphi_2) = \msf{sem}_w(\varphi_1' \; \msf{o} \; \varphi_2')
	\end{equation*}
	Hence, by Remark~\ref{rmk:sufficient_condition}, the pair the $(\LTL(\prop),w)$-pair $(\msf{SEM}_w,\msf{sem}_w)$ satisfies the inductive property. Therefore, by Theorem~\ref{thm:size_separation}, for all $\LTL$-fragments $\msf{L}$, for all inputs $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{W}(\prop))$, if there is an $\msf{L}$-separating formula, there is one of size at most:
	\begin{equation*}
		\prod_{w \in S} |\msf{SEM}_{w}| = \prod_{w \in S} 2^{|w|} = 2^{\sum_{w \in S} |w|}
	\end{equation*}
\end{proof}

\section{Proof of Corollary~\ref{coro:ctl_logic}}
\label{proof:corollary_ctl}
As mentioned in the main part of the paper, we are actually going to show the result of Corollary~\ref{coro:ctl_logic} with $\ATL$-formulas evaluated on concurrent game structures, which are more general than $\CTL$-formulas evaluated on actionless Kripke structures. That way, we recover (in a straightforward manner) the results previously established in \cite{DBLP:conf/fm/BordaisNR24} about the minimal size of separating $\ATL$-formulas, thus illustrating the usefulness of Theorem~\ref{thm:size_separation}. For the remainder of this section, we use the formalism (for concurrent game structures and $\ATL$-formulas) of \cite{DBLP:conf/fm/BordaisNR24}, that we recall almost verbatim below. 

Let us first introduce formally the concurrent game structures on which $\ATL$-formulas will be evaluated. We let $\N_1 := \{ i \in \N \mid i \geq 1\}$.
\begin{definition}
	\label{def:CGS}
	A concurrent game structure is described by a tuple $C = (Q,I,k,P, \pi, d,\delta)$ where $Q$ is the finite set of states, $I \subseteq Q$ is the set of initial states, $k \in \N_1$ is the number of agents, $P$ is the finite non-empty set of propositions (or observations), $\pi: Q\mapsto 2^{P}$ maps each state $q\in Q$ to the set of propositions $\pi(q) \subseteq P$ that hold in $q$, $d: Q \times \Interval{1,k} \rightarrow \N_1$ maps each state and agent to the number of actions available to that agent at that state, and $\delta: Q_\msf{Act} \rightarrow Q$ maps every state and tuple of one action per agent to the successor state, where $Q_\msf{Act} := \cup_{q \in Q} Q_\msf{Act}(q)$ with $Q_\msf{Act}(q) := \{ (q,\alpha_1,\ldots,\alpha_k) \mid \forall a \in \Ag,\; \alpha_a \in \brck{1,d(q,a)} \}$. 
	\iffalse
	\begin{itemize}
		\item $Q$ is the finite set of states;
		\item $I \subseteq Q$ is the set of initial states;
		\item $k \in \N_1$ is the number of agents, we denote by $\Ag := \brck{1,k}$ the set of $k$ agents;
		\item $\prop$ is the finite set of observations or what we call propositions;
		\item $\pi: Q\mapsto 2^{\mathcal{P}}$ %is a function that 
		maps each state $q\in Q$ to the set of propositions $\mathcal{P}'\subseteq \mathcal{P}$ in $q$;
		%\item $\sigma: Q\mapsto \{1,\cdots k\}$ is a function that maps each state $s\in Q$ to a agent $a\in \{1,\cdots, k\}$ that is supposed to play in $s$;
		\item $d: Q \times \brck{1,k} \rightarrow \mathbb{N}^+$ maps each state and agent to the number of actions available to that agent at that state;
		\item $\delta: Q_\msf{Act} \rightarrow Q$ is the function mapping every state and tuple of one action per agent to the next state, where $Q_\msf{Act} := \cup_{q \in Q} Q_\msf{Act}(q)$ with $Q_\msf{Act}(q) := \{ (q,\alpha_1,\ldots,\alpha_i) \mid \forall a \in \Ag,\; \alpha_a \in \brck{1,d(q,a)} \}$. 
	\end{itemize}
	\fi

	For all $q \in Q$ and $A \subseteq \Ag$, we let $\msf{Act}_A(q) := \{ \alpha = (\alpha_a)_{a \in A} \in \prod_{a \in A} %\mid \forall a \in \Ag,\; \alpha_a \in 
	\{a\} \times \brck{1,d(q,a)} \}$. Then, for all tuple $\alpha% = (\alpha_a)_{a \in A} 
	\in \msf{Act}_A(q)$ of one action per agent in $A$, we let: 
	\begin{equation*}
		\msf{Succ}(q,\alpha) := \{ q' \in Q \mid \exists \alpha' %= (\alpha'_a)_{a \in \Ag \setminus A} 
		\in \msf{Act}_{\Ag \setminus A}(q),\; \delta(q,(\alpha,\alpha')) = q' \}
	\end{equation*}
\end{definition}
Unless otherwise stated, a CGS $C$ refers to the tuple $C = (Q,I,k,P,\pi,d,\delta)$.

In a concurrent game structure, a strategy for an agent prescribes what to do as a function of the finite sequence of states seen so far. Moreover, given a coalition of agents and a tuple of one strategy per agent in the coalition, we define the set of infinite sequences of states that can occur with this tuple of strategies. This is defined below.
\begin{definition}
	Consider a concurrent game structure $C$ and an agent $a \in \Ag$. A \emph{strategy} for Agent $a$ is a function $s_a: Q^+ \rightarrow \N_1$ such that, for all $\rho = \rho_0 \dots \rho_n \in Q^+$, we have $s_a(\rho) \leq d(\rho_n,a)$. We let $\msf{S}_a$ denote the set of strategies available to Agent $a% \in \brck{1,k}
	$.

	Given a coalition (or subset) of agents $A \subseteq \Ag$, a \emph{strategy profile} for the coalition $A$ is a tuple $s = (s_a)_{a \in A}$ of one strategy per agent in $A$. We denote by $\msf{S}_A$ the set of strategy profiles for the coalition $A$. %Given any such strategy profile 
	For all $s \in \msf{S}_A$ %, for all states 
	and $q \in Q$, we let $\msf{O}(q,s) \subseteq Q^\omega$ denote the set of infinite paths $\rho$ compatible with %the strategy profile 
	$s$ from $q$:
	\begin{equation*}
		\msf{O}(q,s) := \{ \rho \in Q^\omega \mid \rho[0] = q,\; \forall i \in \N, \rho[i+1] \in \msf{Succ}(\rho[i],(s_a(\rho[0] \cdots \rho[i]))_{a \in A}) \}
	\end{equation*}
	%Then, we let:
	%\begin{equation*}
	%	\msf{Out}^\prop(q,s) := \{ \pi^\omega(\rho) \in (2^\prop)^\omega \mid \rho \in \msf{Out}^Q(q,s) \}
	%\end{equation*}
	%denote the set of infinite sequences of observations that are compatible with the strategy profile $s$ from $q$.
\end{definition}

Let us define below the syntax, models, and semantics of the logic ATL.
\begin{definition}
	\label{def:atl}
	Consider a non-empty finite set of propositions $\prop$. The $\ATL(\prop)$-syntax is as follows, with $p\in \prop$ and $A \subseteq \N$ is a coalition of players:
	\begin{equation*}
		\varphi ::= p \mid \neg \varphi \mid \varphi \vee \varphi \mid \varphi \wedge \varphi \mid \fanBrOp{A} \lX \varphi \mid \fanBrOp{A} \lF \varphi \mid \fanBrOp{A} \lG \varphi \mid \fanBrOp{A} (\varphi \lU \varphi)
	\end{equation*}
	The models $\mathcal{C}(\prop)$ on which $\ATL(\prop)$-formulas are evaluated are the concurrent game structures $C$ for which $P \subseteq \prop$. Formally:
	\begin{equation*}
		\mathcal{C}(\prop) := \{ C = (Q,I,k,P, \pi, d,\delta) \mid P \subseteq \prop \}
	\end{equation*}

	Given a concurrent game structure $C \in \mathcal{C}(\prop)$, and a $\msf{CTL}(\prop)$-formula $\varphi$, we define when $\varphi$ is satisfied by a state $q$ inductively as follows:

	\begin{minipage}[t]{0.2\textwidth}
		\begin{align*}
			& q \models p & \text{ iff } & p \in \pi(q) \\
			& q \models \neg \varphi & \text{ iff } & q \not\models \varphi \\
			& q \models \varphi_1 \vee \varphi_2 & \text{ iff } & q \models \varphi_1 \text{ or } q \models \varphi_2\\
			& q \models \fanBrOp{A} \lF \varphi & \text{ iff } & \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \\
			&&& \exists i \in \N,\; \rho[i:] \models \varphi \\
		\end{align*}
	\end{minipage}
	\begin{minipage}[t]{0.05\textwidth}
		\begin{align*}
			\mid \\
			\mid \\
			\mid \\
			\mid \\
			\mid \\
		\end{align*}
	\end{minipage}
	\begin{minipage}[t]{0.5\textwidth}
		\begin{align*}
			& q \models \fanBrOp{A} \lX \varphi & \text{ iff } & \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \\
			&&& \rho[1:] \models \varphi \\
			& q \models \varphi_1 \wedge \varphi_2 & \text{ iff } & q \models \varphi_1 \text{ and } q \models \varphi_2\\
			& q \models \fanBrOp{A} \lG \varphi & \text{ iff } & \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \\
			&&& \forall i \in \N,\; \rho[i:] \models \varphi \\
		\end{align*}
	\end{minipage}
	Furthermore:
	\begin{equation*}
		q \models \fanBrOp{A} (\varphi_1 \lU \varphi_2) \text{ iff } \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; 
		\exists i \in \N,\; \rho[i:] \models \varphi_2,\; \forall j \leq i-1,\; \rho[j:] \models \varphi_1
	\end{equation*}
	Then, a concurrent game structure $C$ satisfies an $\ATL$-formula $\varphi$, i.e. $C \models \varphi$, if, for all $q \in I$, we have $q \models \varphi$. 
\end{definition}

Let us now state the corollary generalizing Corollary~\ref{coro:ctl_logic} to the case of $\ATL$-formulas evaluated on concurrent game structures.
\begin{corollary}
	\label{coro:atl_logic}
	Consider a non-empty set of propositions $\prop$, and any ATL-fragment $\msf{L}$ of $\msf{ATL}(\prop)$. Then, for all inputs $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{C}(\prop))$, if there is a separating formula, there is one of size at most $2^{n}$, with $n := \sum_{C \in \mathcal{S}} |Q_C|$.
\end{corollary}
Before we prove this corollary, let us prove that it implies Corollary~\ref{coro:ctl_logic} (with $\CTL$-formulas). 
\begin{proof}[Proof of Corollary~\ref{coro:ctl_logic}]
	Consider an input $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{K}(\prop))$. Any actionless Kripke structure $K = (Q,I,\delta,P,\pi)$ in $\mathcal{K}(\prop)$ can be seen as a concurrent game structures $C = (Q,I,k,P,\pi,d,\delta)$ with only one agent, i.e. $k = 1$. In this context, the $\ATL$-quantifier $\fanBrOp{A}$ corresponds to the $\CTL$-path quantifier $\exists$ if $1 \in A$, and to the $\CTL$-path quantifier $\forall$ if $1 \notin A$. The bound of Corollary~\ref{coro:atl_logic} can then be applied directly to the case of Kripke structures and $\CTL$-formulas.
\end{proof}

Let us now proceed to the proof of Corollary~\ref{coro:atl_logic}. 
\begin{proof}[Proof of Corollary~\ref{coro:atl_logic}]
	Let us apply Theorem~\ref{thm:size_separation}. Consider any concurrent game structure $C = (Q_C,I,k,P,\pi,d,\delta)$. We let $\msf{SEM}_C := 2^{Q_C}$, and for all $\ATL(\prop)$-formulas $\varphi \in \msf{Fm}_{\ATL(\prop)}$:
	\begin{equation*}
		\msf{sem}_C(\varphi) := \{ q \in Q_C \mid q \models \varphi \}
	\end{equation*}
	Let us show that the $(\ATL(\prop),C)$-pair $(\msf{SEM}_C,\msf{sem}_C)$ inductively captures the $\ATL(\prop)$-semantics. First of all, it captures the $\ATL(\prop)$-semantics for exactly the same reason that the $(\ML(\prop,\act),K)$-pair $\Theta_K$ (from Example~\ref{ex:Kripke_structures_SEM}) captures the $\ML(\prop,\act)$-semantics (recall Lemma~\ref{lem:modal_logic_pair_captures_semantics}). Let us now focus on the inductive property. Consider two $\ATL$-formulas $\varphi,\varphi'$ such that $\msf{sem}_{C}(\varphi) = \msf{sem}_{C}(\varphi')$. Then, for all $q \in Q_C$, and coalitions of agents $A \subseteq \llbracket 1,k \rrbracket$, we have:
	\begin{align*}
		q \models \fanBrOp{A} \lX \varphi & \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \rho[1:] \models \varphi \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \rho[1:] \in \msf{sem}_C(\varphi) \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \rho[1:] \in \msf{sem}_C(\varphi') \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \rho[1:] \models \varphi' \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; q \models \fanBrOp{A} \lX \varphi'
	\end{align*}
	This is similar for the temporal operator $\lF$:
	\begin{align*}
		q \models \fanBrOp{A} \lF \varphi & \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \exists i \in \N,\; \rho[i:] \models \varphi \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \exists i \in \N,\; \rho[i:] \in \msf{sem}_C(\varphi) \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \exists i \in \N,\; \rho[i:] \in \msf{sem}_C(\varphi') \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; \exists i \in \N,\; \rho[i:] \models \varphi' \\ 
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; q \models \fanBrOp{A} \lF \varphi'
	\end{align*}
	The case of the temporal operator $\lG$ is identical to the case of the temporal $\lF$, except that $\exists i \in \N$ is replaced by $\forall i \in \N$. 

	Consider now four $\ATL$-formulas $\varphi_1,\varphi_2,\varphi_2',\varphi_1'$ such that $\msf{sem}_{C}(\varphi_1) = \msf{sem}_{C}(\varphi_1')$ and $\msf{sem}_{C}(\varphi_2) = \msf{sem}_{C}(\varphi_2')$. Then, for all $q \in Q_C$, we have:
	\begin{align*}
		q \models \fanBrOp{A} \varphi_1 \lU \varphi_2 & \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; 
		\exists i \in \N,\; \rho[i:] \models \varphi_2,\; \forall j \leq i-1,\; \rho[j:] \models \varphi_1 \\
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; 
		\exists i \in \N,\; \rho[i:] \in \msf{sem}_C(\varphi_2),\; \forall j \leq i-1,\; \rho[j:] \models \msf{sem}_C(\varphi_1) \\
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; 
		\exists i \in \N,\; \rho[i:] \in \msf{sem}_C(\varphi_2'),\; \forall j \leq i-1,\; \rho[j:] \models \msf{sem}_C(\varphi_1') \\
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; \forall \rho \in \msf{O}(q,s),\; 
		\exists i \in \N,\; \rho[i:] \models \varphi_2',\; \forall j \leq i-1,\; \rho[j:] \models \varphi_1' \\
		& \Longleftrightarrow \exists s \in \msf{S}_A,\; q \models \fanBrOp{A} \varphi_1' \lU \varphi_2' 
	\end{align*}

	We can therefore apply Remark~\ref{rmk:sufficient_condition} (since propositional operators straightforwardly satisfy the condition of this lemma) and obtain that the $(\ATL(\prop),C)$-pair $(\msf{SEM}_C,\msf{sem}_C)$ satisfies the inductive property. Therefore, by Theorem~\ref{thm:size_separation}, for all $\ATL$-fragments $\msf{L}$, for all inputs $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{C}(\prop))$, if there is an $\msf{L}$-separating formula, there is one of size at most:
	\begin{equation*}
		\prod_{C \in S} |\msf{SEM}_{C}| = \prod_{C \in S} 2^{|Q_C|} = 2^{\sum_{C \in S} |Q_C|}
	\end{equation*}
\end{proof}

\section{Proof of Corollary~\ref{coro:pctl_logic}}
\label{proof:corollary_pctl} 
\begin{proof}
	Let us apply Theorem~\ref{thm:size_separation}. Consider any Markov chain $N = (Q_N,I_N,\mathbb{P}_N,P,\pi)$. We let $\msf{SEM}_N := 2^{Q_N}$, and for all $\PCTL(\prop)$-formulas $\varphi \in \msf{Fm}_{\PCTL(\prop)}$:
	\begin{equation*}
		\msf{sem}_N(\varphi) := \{ q \in Q_N \mid q \models \varphi \} \in \msf{SEM}_N
	\end{equation*}
	Let us show that the $(\PCTL(\prop),N)$-pair $(\msf{SEM}_N,\msf{sem}_N)$ inductively captures the $\PCTL(\prop)$-semantics. First of all, it captures the $\PCTL(\prop)$-semantics since, for all $\varphi \in \msf{Fm}_{\PCTL}$, we have $N \models \varphi$ if and only if $I \subseteq \msf{sem}_N(\varphi)$. Consider now the inductive property. Consider two $\PCTL(\prop)$-formulas $\varphi,\varphi'$ such that $\msf{sem}_{N}(\varphi) = \msf{sem}_{N}(\varphi')$. Then, for all $q \in Q_N$, $\bowtie \in \{\geq,>,\leq,<,=,\neq\}$ and $r \in \mathbb{Q}$, we have:
	\begin{align*}
		q \models \mathbb{P}_{\bowtie r}(\lX \varphi) \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,Q \cdot \msf{sem}_N(\varphi)) \bowtie r \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,Q \cdot \msf{sem}_N(\varphi')) \bowtie r \Longleftrightarrow q \models \mathbb{P}_{\bowtie r}(\lX \varphi')
	\end{align*}
	and:
	\begin{align*}
		q \models \mathbb{P}_{\bowtie r}(\lF \varphi) \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,Q^* \cdot \msf{sem}_N(\varphi)) \bowtie r \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,Q^* \cdot \msf{sem}_N(\varphi')) \bowtie r \Longleftrightarrow q \models \mathbb{P}_{\bowtie r}(\lX \varphi')
	\end{align*}
	and
	\begin{align*}
		q \models \mathbb{P}_{\bowtie r}(\lG \varphi) \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,(\msf{sem}_N(\varphi))^\omega) \bowtie r \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,(\msf{sem}_N(\varphi'))^\omega) \bowtie r \Longleftrightarrow q \models \mathbb{P}_{\bowtie r}(\lG \varphi')
	\end{align*}

	Consider now four $\PCTL$-formulas $\varphi_1,\varphi_2,\varphi_2',\varphi_1'$ such that $\msf{sem}_{N}(\varphi_1) = \msf{sem}_{N}(\varphi_1')$ and $\msf{sem}_{N}(\varphi_2) = \msf{sem}_{N}(\varphi_2')$. Then, for all $q \in Q_C$, we have:
	\begin{align*}
		q \models \mathbb{P}_{\bowtie r}(\varphi_1 \lU \varphi_2) & \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,(\msf{sem}_N(\varphi_1))^* \cdot \msf{sem}_N(\varphi_2)) \bowtie r \\
		& \Longleftrightarrow \overline{\mathbb{P}_{N}}(q,(\msf{sem}_N(\varphi_1'))^* \cdot \msf{sem}_N(\varphi_2')) \bowtie r \\
		& \Longleftrightarrow q \models \mathbb{P}_{\bowtie r}(\varphi_1' \lU \varphi_2')
	\end{align*}

	We can therefore apply Remark~\ref{rmk:sufficient_condition} (since propositional operators straightforwardly satisfy the condition of this lemma) and obtain that the $(\PCTL(\prop),N)$-pair $(\msf{SEM}_N,\msf{sem}_N)$ satisfies the inductive property. Therefore, by Theorem~\ref{thm:size_separation}, for all $\PCTL$-fragments $\msf{L}$, for all inputs $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{N}(\prop))$, if there is an $\msf{L}$-separating formula, there is one of size at most:
	\begin{equation*}
		\prod_{N \in S} |\msf{SEM}_{N}| = \prod_{N \in S} 2^{|Q_N|} = 2^{\sum_{N \in S} |Q_N|}
	\end{equation*}
\end{proof}

\section{Proof of Subsection~\ref{subsec:LTL_case_study}}

\subsection{There does not exist a pair that inductively captures the semantics}
\label{appen:discussion_inexistence}
\begin{proposition}
	Let $K$ denote the Kripke structure depicted in Figure~\ref{fig:Kripke_example}. There is no $(\LTL(\{a,b\}),K)$-pair that inductively capture the $\LTL(\{a,b\})$-semantics.
\end{proposition}
\begin{proof}
	Consider any $(\LTL(\{a,b\}),K)$-pair $\Theta_K = (\msf{SEM}_K,\msf{sem}_K)$ that satisfies the inductive property. Note that, by assumption, the set $\msf{SEM}_K$ is finite. 

	Now, for all $n \geq 1$, we let $\varphi_n^a := \lX^n a$ and $\varphi_n^b := \lX^n b$ be two size-$(n+1)$ $\LTL(\{a,b\})$-formulas. Since $\msf{SEM}_K$ is finite, there is some $1 \leq i < j$ such that $\msf{sem}_K(\varphi_i^a) = \msf{sem}_K(\varphi_j^a)$, which implies $\msf{sem}_K(\varphi_i^a \vee \varphi_i^b) = \msf{sem}_K(\varphi_i^a \vee \varphi_j^b)$. However, we have that:
	\begin{itemize}
		\item $q_1 \models_{\msf{s}} \varphi_i^a \vee \varphi_i^b$; indeed, for all paths $\rho \in \msf{Paths}(q_1)$, we have $\rho[i] \in \{q_2,q_3\}$, hence $\rho \models  \varphi_i^a \vee \varphi_i^b$.
		\item $q_1 \not\models_{\msf{s}} \varphi_i^a \vee \varphi_j^b$; indeed, letting $\rho := q_1 \cdot (q_3)^{i-1} \cdot q_2 \cdot q_3^\omega \in Q^\omega$, we have $\rho \in \msf{Paths}(q_1)$, $\rho[i] = q_2 \not\models a$ and $\rho[j] = q_3 \not\models b$, thus $\rho \not\models \varphi_i^a \vee \varphi_j^b$. 
	\end{itemize}
	It follows that the pair $\Theta_K$ does not capture the $\LTL$-semantics.
\end{proof}

\subsection{Proof of Proposition~\ref{prop:LTL_X_into_LTL_P}}
\label{proof:prop_LTL_X_into_LTL_P}
We say that two ($\msf{L}_{\lX}(\prop)$- or $\LTL_P(\prop)$-) formulas $\varphi,\varphi'$ are equivalent if for all $K \in \mathcal{T}(\prop)$, we have: $K \models \varphi$ if and only if $K \models \varphi'$. Let us now proceed to the proof of Proposition~\ref{prop:LTL_X_into_LTL_P}.
\begin{proof}
	For all $\varphi_1,\varphi_2 \in \msf{Fm}_{\msf{L}_{\lX}}$, we have $\lX (\varphi_1 \wedge \varphi_2)$ equivalent to $(\lX \varphi_1 \wedge \lX\varphi_2)$ and $\lX (\varphi_1 \vee \varphi_2)$ equivalent to $(\lX \varphi_1 \vee \lX\varphi_2)$. In addition, for all $\varphi_1,\varphi_2 \in \msf{Fm}_{\msf{L}_{\lX}}$, we have $\neg \lX \varphi$ equivalent to $\lX \neg \varphi$, $\neg (\varphi_1 \vee \varphi_2)$ equivalent to $(\neg \varphi_1 \wedge \neg \varphi_2)$, and $\neg (\varphi_1 \wedge \varphi_2)$ equivalent to $(\neg \varphi_1 \vee \neg \varphi_2)$. Therefore, for all $\msf{L}_{\lX}$-formulas $\varphi$, there is some formula $\overline{\varphi} = \bigwedge_{i = 1}^n \overline{\varphi_i}$ that is equivalent to $\varphi$ such that $1 \leq n \in \N$ and for all $1 \leq i \leq n$, we have $\overline{\varphi_i} := \bigvee_{1 \leq j \leq n_i} \lX^{k_{i,j}} x_{i,j}$, with, for all $1 \leq j \leq n_i$, $k_{i,j} \in \N$ and $x_{i,j} \in \{ p,\neg p \mid p \in \prop \}$. Let $1 \leq i \leq n$ and assume without loss of generality that we have $k_{i,1} \leq k_{i,2} \leq \ldots \leq k_{i,n_i}$. For all $2 \leq j \leq n_i$, let $l_{i,j} := k_{i,j} - k_{i,j-1} \geq 0$. Then, the formula $\varphi_{i}' := \lX^{k_{i,1}} (x_{i,1} \vee (\lX^{l_{i,2}} (x_{i,2} \vee (\lX^{l_{i,3}} (x_{i,3} \vee \ldots (x_{i,n_i-1} \vee \lX^{l_{i,n_i}} x_{i,n_i}))))))$ is equivalent to the formula $\overline{\varphi_i}$ and is a $\LTL_P$-formula. Therefore, the formula $\varphi' := \bigwedge_{i = 1}^n \varphi_i'$ is a $\LTL_P$-formula that is equivalent to $\varphi$.
\end{proof}

\subsection{Proof of Corollary~\ref{coro:ltl_P_logic}}
\label{proof:coro_ltl_P_logic}
\begin{proof}
	Let us apply Theorem~\ref{thm:size_separation}. Consider an actionless non-blocking Kripke structure $K = (Q,I,\delta,P,\pi) \in \mathcal{T}(\prop)$. Contrary to the other logics, $\LTL_P$ has two types of formulas $\tau$ and $\tau_P$, corresponding to the lines $\varphi$ and $\varphi_P$ respectively is the grammar defining the logic $\LTL_P$. Thus, we need to define the set of semantic values for the types $\tau$ and $\tau_P$. In both cases, it is equal to $2^{Q_K}$, i.e. we let $\msf{SEM}_K(\tau) := 2^{Q_K}$ and $\msf{SEM}_K(\tau_P) := 2^{Q_K}$ (these sets are typed so that their intersection is empty). For all $x \in \{\tau,\tau_P\}$ and $\LTL_P(\prop)$-formulas $\varphi \in \msf{Fm}_{\LTL(\prop)}(x)$, we let:
	\begin{equation*}
		\msf{sem}_K(\varphi) := \{ q \in Q_K \mid q \models_{\msf{s}} \varphi \} \in \msf{SEM}_K(x)
	\end{equation*}
	Let us show that the $(\LTL_P(\prop),K)$-pair $(\msf{SEM}_K,\msf{sem}_K)$ inductively captures the $\LTL_P(\prop)$-semantics. It straightforwardly captures the $\LTL_P(\prop)$-semantics. Let us now focus on the inductive property. It is also straightforward that the $(\LTL_P(\prop),K)$-pair $(\msf{SEM}_K,\msf{sem}_K)$ satisfies this property when considering only formulas in $\msf{Fm}_{\LTL_P(\prop)}(\tau_P)$. Consider now some $\LTL_P$-formula $\varphi \in \msf{Fm}_{\LTL_P(\prop)}(\tau)$. We have that:
	\begin{itemize}
		\item Straightforwardly, $\msf{sem}_K(\lX \varphi) = \{ q \in Q \mid \delta(q) \subseteq \msf{sem}_K(\varphi) \}$.
		\item Furthermore, letting $S := \{ q \in Q \mid \forall \rho \in \msf{Paths}(q),\; \forall i \in \N,\; \rho[i] \in \msf{sem}_K(\varphi) \}$, we have $\msf{sem}_K(\lG \varphi) = S$. Indeed, consider any $q \in \msf{sem}_K(\lG \varphi)$ and any $\rho \in \msf{Paths}(q)$. Then, by definition $\rho \models \lG \varphi$. Consider any $i \in \N$ and $\rho' \in \msf{Paths}(\rho[i])$. Since $\rho[:i-1] \cdot \rho' \in \msf{Paths}(q)$, and thus $\rho[:i-1] \cdot \rho' \models \lG \varphi$, it follows that $\rho' \models \varphi$. This holds for all $\rho' \in \msf{Paths}(\rho[i])$, thus $\rho[i] \in \msf{sem}_K(\varphi)$. This holds for all $i \in \N$ and $\rho \in \msf{Paths}(q)$. Thus, $q \in S$. In fact, we have $\msf{sem}_K(\lG \varphi) \subseteq S$. Consider now some $q \in S$. Let $\rho \in \msf{Paths}(q)$ and $i \in \N$. By definition of $S$, we have $\rho[i] \in \msf{sem}_K(\varphi)$, thus $\rho[i:] \models \varphi$. As this holds for all $i \in \N$, it follows that $\rho \models \lG \varphi$. Hence, $q \in \msf{sem}_K(\lG \varphi)$. In fact, $S \subseteq \msf{sem}_K(\lG \varphi)$. 
		%\item $\msf{sem}_K(\lG \varphi)$ is the largest subset $S \subseteq \msf{sem}_K(\varphi)$ such that, for all $q \in S$, we have $\delta(q) \subseteq S$.  
	\end{itemize}

	Furthermore, for all $\LTL_P$-formulas $\varphi_1,\varphi_2$, we straightforwardly have that: 
	\begin{equation*}
		\msf{sem}_K(\varphi_1 \wedge \varphi_2) = \msf{sem}_K(\varphi_1) \cap \msf{sem}_K(\varphi_2)
	\end{equation*}

	In addition, consider some $\LTL_P$-formula $\varphi \in \msf{Fm}_{\LTL_P(\prop)}(\tau_P)$. Letting $T := \{ q \in Q \mid \forall \rho \in \msf{Paths}(q),\; \exists i \in \N,\; \rho[i] \in \msf{sem}_K(\varphi) \}$, we have $\msf{sem}_K(\lF \varphi) = T$. Indeed, consider any $q \in \msf{sem}_K(\lF \varphi)$ and any $\rho \in \msf{Paths}(q)$. Then, by definition $\rho \models \lF \varphi$. Hence, there is some $i \in \N$ such that $\rho[i:] \models \varphi$. Since $\varphi$ is of type $\tau_P$, this is equivalent $\rho[i] \in \msf{sem}_K(\varphi)$. This holds for all $\rho \in \msf{Paths}(q)$. Thus, $q \in T$. In fact, we have $\msf{sem}_K(\lF \varphi) \subseteq T$. Consider now some $q \in T$. Let $\rho \in \msf{Paths}(q)$. By definition of $T$, there is some $i \in \N$ such that $\rho[i] \in \msf{sem}_K(\varphi)$, thus $\rho[i:] \models \varphi$. Hence, $\rho \models \lF \varphi$. Hence, $q \in \msf{sem}_K(\lF \varphi)$. In fact, $T \subseteq \msf{sem}_K(\lF \varphi)$. 

	%We have that $\msf{sem}_K(\lF \varphi)$ is the least subset $\msf{sem}_K(\varphi) \subseteq S \subseteq Q$ such that, for all $q \in Q$, if $\delta(q) \subseteq S$ then $q \in S$.  

	Furthermore, consider some $\LTL_P$-formula $\varphi'$ of type $\tau$. We have the following. 
	\begin{itemize}
		\item We have $\msf{sem}_K(\varphi \vee \varphi') = \msf{sem}_K(\varphi) \cup \msf{sem}_K(\varphi')$. Indeed, consider any $q \in \msf{sem}_K(\varphi \vee \varphi')$. If $q \notin \msf{sem}_K(\varphi)$, then, since $\varphi$ is of type $\tau_P$, for all $\rho \in \msf{Paths}(q)$, we have $\rho \not\models \varphi$, and thus $\rho \models \varphi'$. That is $q \in \msf{sem}_K(\varphi')$. Hence, we have $\msf{sem}_K(\varphi \vee \varphi') \subseteq \msf{sem}_K(\varphi) \cup \msf{sem}_K(\varphi')$. The reverse inclusion is straightforward.
		\item Letting $V := \{ q \in Q \mid \forall \rho \in \msf{Paths}(q),\; \exists j \in \N,\; \rho[j] \in \msf{sem}_K(\varphi),\; \forall i \leq j-1 \in \N,\; \rho[i] \in \msf{sem}_K(\varphi') \}$, we have $\msf{sem}_K(\varphi' \lU \varphi) = V$. Indeed, consider any $q \in \msf{sem}_K(\varphi' \lU \varphi)$ and any $\rho \in \msf{Paths}(q)$. Then, by definition $\rho \models \varphi' \lU \varphi$. Consider the least $j \in \N$ such that $\rho[j:] \models \varphi$ and for all $i \leq j-1$, $\rho[i:] \models \varphi'$. Since $\varphi$ is of type $\tau_P$, we have $\rho[j] \in \msf{sem}_K(\varphi)$. Furthermore, consider any $i \leq j-1$ and $\rho' \in \msf{Paths}(\rho[i])$. We have $\rho[:i-1] \cdot \rho' \in \msf{Paths}(q)$, thus $\rho[:i-1] \cdot \rho' \models \varphi' \lU \varphi$ and, for all $k \leq i-1$, we have $\rho[k:] \not \models \varphi$, since $\varphi$ is of type $\tau_P$. Hence, we have $\rho' \models \varphi'$. As this holds for all $\rho' \in \msf{Paths}(\rho[i])$, it follows that $\rho[i] \in \msf{sem}_K(\varphi')$. This holds for all $i \leq j-1$ and for all $\rho \in \msf{Paths}(q)$. Thus, $q \in V$. In fact, we have $\msf{sem}_K(\varphi' \lU \varphi) \subseteq V$. Consider now some $q \in V$. Let $\rho \in \msf{Paths}(q)$. By definition of $V$, there is some $j \in \N$ such that $\rho[j] \in \msf{sem}_K(\varphi)$, and for all $i \leq j$, $\rho[i] \in \msf{sem}_K(\varphi)$. It follows that $\rho[j:] \models \varphi$ and, for all $i \leq j$, $\rho[i:] \models \varphi'$. Hence, $\rho \models \varphi' \lU \varphi$. Hence, $q \in \msf{sem}_K(\varphi' \lU \varphi)$. In fact, $V \subseteq \msf{sem}_K(\varphi' \lU \varphi)$. 
	\end{itemize}

	Therefore, by Theorem~\ref{thm:size_separation}, for all $\LTL_P(\prop)$-fragments $\msf{L}$, for all inputs $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{L},\mathcal{T}(\prop))$, if there is an $\msf{L}$-separating formula, there is one of size at most:
	\begin{equation*}
		\prod_{K \in S} |\msf{SEM}_{K}(\tau)| + \prod_{K \in S} |\msf{SEM}_{K}(\tau_P)| = 2 \cdot \prod_{K \in S} 2^{|Q_K|} = 2^{\sum_{K \in S} |Q_K| +1}
	\end{equation*}
\end{proof}

\subsection{Discussion on Proposition~\ref{prop:model_checking}}
\label{proof:prop_model_checking}

In \cite{DBLP:journals/tocl/BaulandM0SSV11}, it is shown that the model checking problem of $\LTL$-formulas on Kripke structures with the operator $\lX$ is $\msf{NP}$-hard. It has to be noted that the semantics considered in \cite{DBLP:journals/tocl/BaulandM0SSV11} is different from what we consider in this paper since we have $q \models_{\msf{s}} \varphi$ if and only if all paths from $q$ satisfy $\varphi$, while in \cite{DBLP:journals/tocl/BaulandM0SSV11} it is required that there exists a path from $q$ that satisfies $\varphi$. However, we believe that, if we considered this other semantic, up to reversing the roles of $\wedge$ and $\vee$, and of $\lF$ and $\lG$ (and not using the operator $\lU$), we would obtain the same results.

In addition, what we show with Proposition~\ref{prop:model_checking} is that, for the logic $\LTL_P$, the model checking problem can be decided in polynomial time. This does not imply that the model checking problem for the logic $\msf{L}_{\lX}$ (i.e. the fragment of $\LTL$ allowing only $\lX$ as temporal operator) can be decided in polynomial time. This is due to the fact that the translation of an $\msf{L}_{\lX}$-formula into an equivalent $\LTL_P$-formula --- as we consider in Proposition~\ref{prop:LTL_X_into_LTL_P} --- may induce an exponential blow up in size. 
\begin{proof}	
	Consider an $\LTL_P$-formula $\varphi$ and an actionless non-blocking Kripke structure $K$. Let us consider the $(\LTL_P(\prop),K)$-pair $(\msf{SEM}_K,\msf{sem}_K)$ from the proof of Corollary~\ref{coro:ltl_P_logic}. To decide if the formula $\varphi$ accepts the structure $K$, it suffices to iteratively compute the set $\msf{sem}_K(\psi) \subseteq Q$ for each sub-formula $\psi \in \msf{Sub}(\varphi)$. Each one of these subsets can be computed in time polynomial in $Q$ as it amounts to compute the set described in the proof of Corollary~\ref{coro:ltl_P_logic}: the operators $\lor,\wedge,\lX$ are straightforwardly handled. As for the other operators, the semantic value can be computed via fixed-point procedure. 
	\begin{itemize}
		\item For all $\LTL_P$-formulas $\varphi$ of type $\tau$, the set $\msf{sem}_K(\lG \varphi)$ corresponds to the largest subset $S \subseteq \msf{sem}_K(\varphi)$ such that, for all $q \in S$, we have $\delta(q) \subseteq S$.
		\item For all $\LTL_P$-formulas $\varphi$ of type $\tau_P$, the set $\msf{sem}_K(\lF \varphi)$  corresponds to the least subset $\msf{sem}_K(\varphi) \subseteq S \subseteq Q$ such that, for all $q \in Q$, if $\delta(q) \subseteq S$, then $q \in S$.
		\item For all $\LTL_P$-formulas $\varphi$ of type $\tau_P$ and $\LTL_P$-formulas $\varphi'$ of type $\tau$, the set $\msf{sem}_K(\varphi' \lU \varphi)$ corresponds to the least subset $\msf{sem}_K(\varphi) \subseteq S \subseteq Q$ such that, for all $q \in \msf{sem}_K(\varphi')$, if $\delta(q) \subseteq S$, then $q \in S$.
	\end{itemize}
\end{proof}
Note that the procedure described above is very classical to decide the model checking for e.g. $\LTL$-formulas on words, $\CTL$-formulas on Kripke structures, $\ATL$-formulas on concurrent game structures, $\PCTL$-formulas on Markov chains, etc. However, it cannot be used for the full logic $\LTL$ evaluated on Kripke structure, as the full logic $\LTL$ does not have such an inductive behavior. 

\section{Proof of Corollary~\ref{coro:finite_automaton}}
\label{proof:corollary_automaton}
To be able to apply Theorem~\ref{thm:size_separation} to prove this corollary, we define below a logic whose formulas are finite words which are evaluated on finite automaton.
\begin{definition}
	\label{def:finite_words_on_atutomaton}
	Consider a non-empty alphabet $\Sigma$. We define the logic $\msf{FW}(\Sigma)$ corresponding to the finite words in $\Sigma^*$. The $\msf{FW}(\Sigma)$-syntax is as follows, with $a \in \Sigma$ a letter:
	\begin{equation*}
		\msf{u} ::= \varepsilon \mid \msf{u} \cdot a
	\end{equation*}
	The models $\mathcal{FA}(\Sigma)$ on which $\msf{FW}(\Sigma)$-formulas are evaluated is the set of finite automata whose alphabet is equal to $\Sigma$, as defined below.
	\begin{equation*}
		\mathcal{FA}(\Sigma) := \{ \mathcal{A} = (Q,\Pi,I,\delta,F) \mid \Pi = \Sigma \}
	\end{equation*}

	Given a finite automaton $A \in \mathcal{FA}(\Sigma)$, and a $\msf{FW}(\Sigma)$-formula $\msf{u}$, we define when $\msf{u}$ is satisfied by the automaton $A$ via the corresponding finite word in $\Sigma^*$. Specifically, we inductively define a function $f_{\msf{FW}(\Sigma)}: \msf{Fm}_{\msf{FW}(\Sigma)} \to \Sigma^*$ as follows: 
	\begin{align*}
		f_{\msf{FW}(\Sigma)}(\varepsilon) & := \varepsilon \\
		f_{\msf{FW}(\Sigma)}(\msf{u} \cdot a) & := f_{\msf{FW}(\Sigma)}(\msf{u}) \cdot a
	\end{align*}

	Then, a finite automaton $A \in \mathcal{FA}(\Sigma)$ satisfies an $\msf{FW}(\Sigma)$-formula $\msf{u}$, i.e. $A \models \msf{u}$, if the automaton $A$ accepts the finite word $f_{\msf{FW}(\Sigma)}(\msf{u}) \in \Sigma^*$.
\end{definition}

This definition satisfies the lemma below.
\begin{lemma}
	\label{lem:logic_words}
	Consider a non-empty alphabet $\Sigma$. The function $f_{\msf{FW}(\Sigma)}: \msf{Fm}_{\msf{FW}(\Sigma)} \to \Sigma^*$ is a bijection such that, for all $\msf{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$, we have $\msf{sz}(\msf{u}) - 1 = |f_{\msf{FW}(\Sigma)}(\msf{u})|$. 

	For all $u \in \Sigma^*$, we denote by $\tilde{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$ the $\msf{FW}(\Sigma)$-formula such that $f_{\msf{FW}(\Sigma)}(\tilde{u}) = u$.
\end{lemma}
\begin{proof}
	This can be proved straightforwardly by induction on $\msf{FW}(\Sigma)$-formulas.
\end{proof}

We can then apply Theorem~\ref{thm:size_separation} to this finite-word logic to obtain a corollary of which Corollary~\ref{coro:finite_automaton} is a straightforward consequence.
\begin{lemma}
	\label{lem:finite_words_logic}
	Consider a non-empty alphabet $\Sigma$. For all $\mathcal{FA}(\Sigma)$-samples $\mathcal{S} = (\mathcal{P},\mathcal{N})$, if there is a $\msf{FW}(\Sigma)$-formula that is $\mathcal{S}$-separating, then there is one such $\msf{FW}(\Sigma)$-formula of size at most $2^{n}$, with $n := \sum_{\mathcal{A} \in \mathcal{S}} |Q_\mathcal{A}|$.
\end{lemma}
Before we proceed to the proof of this lemma, let us use it to prove Corollary~\ref{coro:finite_automaton}.
\begin{proof}[Proof of Corollary~\ref{coro:finite_automaton}]
	Consider a pair $(\mathcal{P},\mathcal{N})$ of finite sets of finite automata, and assume that there exists a finite word $u \in \Sigma^*$ accepted by all automata in $\mathcal{P}$ and rejected by all automata in $\mathcal{N}$. By Lemma~\ref{lem:logic_words}, the $\msf{FW}(\Sigma)$-formula $\tilde{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$ is such that, for all $A \in \mathcal{P}$, we have $A \models \tilde{u}$, and for all $A \in \mathcal{N}$, we have $A \not\models \tilde{u}$. Thus, the sample $\mathcal{S} = (\mathcal{P},\mathcal{N})$ is a positive instance of the decision problem $\msf{PvLn}(\msf{FW}(\Sigma),\mathcal{FA}(\Sigma))$. Hence, by Lemma~\ref{lem:finite_words_logic}, there is some $\msf{FW}(\Sigma)$-formula $\tilde{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$, for some $u \in \Sigma^*$, that is $\mathcal{S}$-separating and of size at most $2^{n}$, with $n := \sum_{\mathcal{A} \in \mathcal{S}} |Q_\mathcal{A}|$. By Lemma~\ref{lem:logic_words}, the word $u \in \Sigma^*$ is accepted by all the automata in $\mathcal{P}$, rejected by all the automata in $\mathcal{N}$, and such that $|u| \leq 2^n - 1$.
\end{proof}

Let us now proceed to the proof of Lemma~\ref{lem:finite_words_logic}. 
\begin{proof}[Proof of Lemma~\ref{lem:finite_words_logic}]
	Let us apply Theorem~\ref{thm:size_separation}. Consider an automaton $A \in \mathcal{FA}(\Sigma)$. We let $\msf{SEM}_A := 2^Q$, and for all $\msf{FW}(\Sigma)$-formulas $\tilde{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$ (for $u \in \Sigma^*$):
	\begin{equation*}
		\msf{sem}_A(\tilde{u}) := \{ q \in Q \mid \text{there is an $A$-run $\rho$ on $u$ such that }\head{\rho} = q\}
	\end{equation*}
	Let us show that the $(\msf{FW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ inductively captures the $\msf{FW}(\Sigma)$-semantics. It clearly captures the $\msf{FW}(\Sigma)$-semantics since we have $A \models \tilde{u}$ if and only if there is an $A$-run $\rho$ on $u$ such that $\head{\rho} \in F$. As for the inductive property, we have that, for all $\msf{FW}(\Sigma)$-formulas $\tilde{u} \in \msf{Fm}_{\msf{FW}(\Sigma)}$ and letters $a \in \Sigma$, we have:
	\begin{align*}
		\msf{sem}_A(\tilde{u \cdot a}) & = \{ q \in Q \mid \text{there is an $A$-run $\rho$ on $u \cdot a$ such that }\head{\rho} = q\} \\
		& = \{ q \in Q \mid \exists \rho \in Q^{|u\cdot a|+1},\;  \forall i \in \llbracket 0,|\rho|-2 \rrbracket,\; \rho[i+1] \in \delta(\rho[i],(u\cdot a)[i]), \\
		& \phantom{= \{ \}q \in Q \mid \exists \rho \in Q^{|u\cdot a|+1},\; } \rho[0] \in I,\; \head{\rho} = q \} \\
		& = \{ q \in Q \mid \exists \rho \in Q^{|u|+1},\;  \forall i \in \llbracket 0,|\rho|-2 \rrbracket,\; \rho[i+1] \in \delta(\rho[i],u[i]), \\
		& \phantom{= \{ \}q \in Q \mid \exists \rho \in Q^{|u\cdot a|+1},\; } \rho[0] \in I,\; q \in \delta(\head{\rho},a)\} \\
		& = \{ q \in Q \mid \exists q' \in \msf{sem}_A(\tilde{u}),\; q \in \delta(q',a) \} =  \bigcup_{q \in \msf{sem}_A(\tilde{u})} \delta(q,a)
	\end{align*}
	%
	%\begin{equation*}
	%	\msf{sem}_A(\tilde{u} \cdot a) = \{ q \in Q \mid \exists q' \in \msf{sem}_A(\tilde{u}),\; q \in \delta(q',a) \}
	%\end{equation*}
	Hence, by Remark~\ref{rmk:sufficient_condition}, the pair the $(\msf{FW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ inductively captures the $\msf{FW}(\Sigma)$-semantics. Therefore, by Theorem~\ref{thm:size_separation}, $\mathcal{S} = (\mathcal{P},\mathcal{N})$ of the decision problem $\msf{PvLn}(\msf{FW}(\Sigma),\mathcal{FA}(\Sigma))$, if there is an $\msf{FW}(\Sigma)$-formula that is $\mathcal{S}$-separating, there is one of size at most:
	\begin{equation*}
		\prod_{A \in \mathcal{S}} |\msf{SEM}_{A}| = \prod_{A \in \mathcal{S}} 2^{|Q_A|} = 2^{\sum_{A \in \mathcal{S}} |Q_A|}
	\end{equation*}
\end{proof}

\section{Proof of Corollary~\ref{coro:parity_automaton}}
\label{proof:corollary_parity_automaton}
The case of parity automata and ultimately periodic words is similar to the case of finite automata and finite words, with several additional difficulties. 

We first tackle the case of periodic words on parity automata, and we then deduce Corollary~\ref{coro:parity_automaton} (which deals with ultimately periodic words) with the help of Corollary~\ref{coro:finite_automaton}. Let us first define a periodic words logic. 	
\begin{definition}
	\label{def:periodic_words_on_parity_atutomaton}
	Consider a non-empty alphabet $\Sigma$. We define the logic $\msf{PW}(\Sigma)$ of periodic words $w = v^\omega \in \Sigma^\omega$. The $\msf{PW}(\Sigma)$-syntax is given by the grammar below, with $a \in \Sigma$ a letter: 		
	\begin{align*}
		\msf{v} & ::= a \mid \msf{v} \cdot a
	\end{align*}
	%More formally, the syntax is defined by $(\{\tau_{\msf{u}},\tau_{\msf{v}}\},\{\tau_{\msf{v}}\},\msf{Op},\tau,T)$ with $\msf{Op}_0 := \{ \varepsilon \mid a \in \Sigma \}$, $\msf{Op}_1 := \{ \msf{Inf},\msf{App}^{\msf{w}}_a,\msf{App}^{\msf{v}}_a\mid a \in \Sigma \}$, and for all $a \in \Sigma$: $\tau_{a} = \tau_{\msf{App}^{\msf{v}}_a} := \tau_{\msf{v}}$, $\tau_{\msf{App}^{\msf{w}}_a} = \tau_{\msf{Inf}} := \tau_{\msf{w}}$, and $T(\msf{Inf},1) = T(\msf{App}^{\msf{v}}_a,1) = \{\tau_{\msf{v}}\}$, and $T(\msf{App}^{\msf{w}}_a,1) = \{\tau_{\msf{w}}\}$. Thus, the ultimately periodic word $a_1 \cdot a_2 \cdot a_3 \cdot (a_4 \cdot a_5)^\omega$ is represented by the formula $\msf{App}_{a_1}^{\msf{w}}( \msf{App}_{a_2}^{\msf{w}}( \msf{App}_{a_3}^{\msf{w}}( \msf{Inf}(\msf{App}_{a_4}^{\msf{v}}(a_5)))))$

	The models $\mathcal{PA}(\Sigma)$ on which $\msf{PW}(\Sigma)$-formulas are evaluated is the set of parity automata defined below.
	\begin{equation*}
		\mathcal{PA}(\Sigma) := \{ \mathcal{A} = (Q,\Pi,I,\delta,\pi) \mid \Pi = \Sigma \}
	\end{equation*}

	Then, given a parity automaton $A \in \mathcal{PA}(\Sigma)$ and a $\msf{PW}(\Sigma)$-formula $\msf{v}$, we define when $\msf{v}$ is satisfied by $A$. To do so, we are going to consider the periodic word in $\Sigma^{\omega}$ corresponding to the formula $\msf{v}$. First, we inductively define a function $f_{\msf{PW}(\Sigma)}: \msf{Fm}_{\msf{PW}(\Sigma)} \rightarrow \Sigma^+$ as follows: 
	\begin{align*}
		f_{\msf{PW}(\Sigma)}(a) & := a \\
		f_{\msf{PW}(\Sigma)}(\msf{v} \cdot a) & := 	f_{\msf{PW}(\Sigma)}(\msf{v}) \cdot a
	\end{align*}
	Then, we let $\Sigma^{+\omega} := \{ v^\omega \mid v \in \Sigma^+ \}$ denote the set of  periodic words, and we let $g_{\msf{PW}(\Sigma)}: \msf{Fm}_{\msf{PW}(\Sigma)} \to \Sigma^{+\omega}$ be such that, for all $\msf{v} \in \msf{Fm}_{\msf{PW}(\Sigma)}$, we have $g_{\msf{PW}(\Sigma)}(\msf{v}) := (f_{\msf{PW}(\Sigma)}(\msf{v}))^\omega$. 

	Then, a parity automaton $A \in \mathcal{PA}(\Sigma)$ satisfies an $\msf{PW}(\Sigma)$-formula $\msf{v}$, i.e. $A \models \msf{v}$, if the periodic word $g_{\msf{PW}(\Sigma)}(\msf{v})$ is accepted by the parity automaton $A$. 
\end{definition}

This definition satisfies the lemma below.
\begin{lemma}
	\label{lem:logic_periodic_words}
	Consider a non-empty alphabet $\Sigma$. The function $f_{\msf{PW}(\Sigma)}: \msf{Fm}_{\msf{PW}(\Sigma)} \to \Sigma^+$ is a bijection and, for all $\msf{v} \in \msf{Fm}_{\msf{PW}(\Sigma)}$, we have $\msf{sz}(\msf{v}) =  |f_{\msf{PW}(\Sigma)}(\msf{v})|$. 

	For all $v \in \Sigma^+$, we denote by $\overline{v} \in \msf{Fm}_{\msf{PW}(\Sigma)}$ the $\msf{PW}(\Sigma)$-formula for which $f_{\msf{PW}(\Sigma)}(\overline{v}) = v$.
\end{lemma}
\begin{proof}
	This can be proved straightforwardly by induction on $\msf{Fm}_{\msf{PW}(\Sigma)}$.
\end{proof}

We can then apply Theorem~\ref{thm:size_separation} to this periodic-word logic to obtain a lemma from which we will be able to deduce Corollary~\ref{coro:parity_automaton}.
\begin{lemma}
	\label{lem:periodic_words_logic}
	Consider a non-empty alphabet $\Sigma$. For all $\mathcal{PA}(\Sigma)$-samples $\mathcal{S} = (\mathcal{P},\mathcal{N})$, if there is a $\mathcal{S}$-separating $\msf{PW}(\Sigma)$-formula, there is one of size at most $2^{k}$, with $k := \sum_{A \in \mathcal{S}} |Q_A|^2 \cdot n_A$.
\end{lemma}
\begin{proof}
	Let us apply Theorem~\ref{thm:size_separation}. Consider a parity automaton $A \in \mathcal{PA}(\Sigma)$. We let $\msf{SEM}_A := \{ Q \to 2^{Q \times \pi(Q)} \}$, and for all $\msf{PW}(\Sigma)$-formulas $\overline{v} \in \msf{Fm}_{\msf{FW}(\Sigma)}$ (for $v \in \Sigma^+$), we let $\msf{sem}_A(\overline{v}): Q \to 2^{Q \times \pi(Q)}$ be such that, for all $q \in Q$:
	\begin{align*}
		\msf{sem}_A(\overline{v})(q) := \{ (q',n) \in Q \times \Interval{0,n_A} \mid & \exists \rho \in Q^{|v|+1}:\; \forall i \in \Interval{0,|\rho|-2},\; \rho[i+1] \in \delta(\rho[i],v[i]), \\
		& \rho[0] = q,\; \head{\rho} = q', \; \max_{0 \leq i \leq |\rho|-1} \pi(\rho[i]) = n \}
	\end{align*}

	Let us show that the $(\msf{PW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ inductively captures the $\msf{PW}(\Sigma)$-semantics. Let us first show that it satisfies the inductive property. For all $\msf{PW}(\Sigma)$-formulas $\overline{v} \in \msf{Fm}_{\msf{PW}(\Sigma)}$ and letters $a \in \Sigma$, we have $\msf{sem}_A(\overline{v} \cdot a): Q \to 2^{Q \times \pi(Q)}$ such that, for all $q \in Q$
	\begin{align*}
		\msf{sem}_A(\overline{v} \cdot a)(q) = & \{ (q',n') \in Q \times \Interval{0,n_A} \mid \exists (q'',n'') \in \msf{sem}_A(\overline{v}):
		q' \in \delta(q'',a),\; n' = \max(\pi(q'),n'') \}
	\end{align*}
	Hence, by Remark~\ref{rmk:sufficient_condition}, the pair the $(\msf{PW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ satisfies the inductive property. Let us now focus on capturing the $\msf{FW}(\Sigma)$-semantics. Given any $v \in \Sigma^+$, we let $\msf{Priorities}_A(v) := \{ n \in \pi(Q) \mid \text{ there is an }A\text{-run }\rho\text{ on }v^\omega\text{ s.t. } n := \max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; \pi(\rho[j]) = k \}  \}$. Note that $v^\omega$ is accepted by $A$ if and only if there is some even integer in $\msf{Priorities}_A(v)$. Now, given any $h: Q \to 2^{Q \times \pi(Q)}$ and $q \in Q$, we let:
	\begin{align*}
		\msf{Sequences}_A(h,q) := \{ & (q_0,n_0) \cdot (q_1,n_1) \cdots \in (Q \times \pi(Q))^\omega \mid \\ & (q_0,n_0) \in h(q),\; \forall i\in \N,\; (q_{i+1},n_{i+1}) \in h(q_i) \}
	\end{align*}
	and 
	\begin{align*}
		\msf{Priorities}_A(h) := \{ n \in \pi(Q) \mid & \; \exists q \in I,\; \exists (q_0,n_0) \cdot (q_1,n_1) \cdots \in \msf{Sequences}_A(h,q): \\
		%& \phantom{m}\rho = \body{\rho_0} \cdot \body{\rho_1} \cdot \body{\rho_2} \cdots,\; \\
		& \; n = \max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; n_j = k \} \}
	\end{align*}
	Then, for all $v \in \Sigma^+$, let us show that:
	\begin{equation*}
		\msf{Priorities}_A(v) = \msf{Priorities}_A(\msf{sem}_A(\overline{v}))
	\end{equation*} 

	Let $t := |v| \geq 1$. Consider %some $n \in \msf{Priorities}_A(v)$ and 
	an $A$-run $\rho$ on $v^\omega$.  %We let $n_0 := \max \{ \pi(\rho[j]) \mid 0 \leq j \leq t-1 \} \in \pi(Q)$ and f
	For all $m \in \N$, we let $n_m := \max \{ \pi(\rho[j]) \mid m \cdot t \leq j \leq (m+1) \cdot t \} \in \pi(Q)$. By definition of an $A$-run and of $\msf{sem}_A(\overline{v})$, we have: 
	\begin{equation*}
		\forall m \in \N,\; (\rho[(m+1) \cdot t],n_m) \in \msf{sem}_A(\overline{v})(\rho[m \cdot t])
	\end{equation*}
	Thus, $((\rho[(m+1) \cdot t],n_m))_{m \in \N} \in \msf{Sequences}_A(\msf{sem}_A(\overline{v}),\rho[0])$, with $\rho[0] \in I$. Furthermore, we have:
	\begin{equation*}
		\max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; \pi(\rho[j]) = k \} = \max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; n_j = k \}
	\end{equation*}
	Since this holds for all $A$-runs $\rho$ on $v^\omega$, it follows that $\msf{Priorities}_A(v) \subseteq \msf{Priorities}_A(\msf{sem}_A(\overline{v}))$.

	Reciprocally, consider some $((q_m,n_m))_{m \in \N} \in \msf{Sequences}_A(\msf{sem}_A(\overline{v}),q)$, for some $q \in I$. By definition, for all $m \in \N$, there is some $\rho^m \in Q^{t+1}$ such that: 
	\begin{equation*}
		\rho^m[0] = q_m,\; \head{\rho^m} = q_{m+1},\; \forall 0 \leq i \leq t-1,\; \rho^m[i+1] \in \delta(\rho^m[i],v[i]),\; \max_{0 \leq i \leq t} \pi(\rho[i]) = n_m  
	\end{equation*}
	Let $\rho := \body{\rho^0} \cdot \body{\rho^1} \cdot \body{\rho^2} \cdots \in Q^\omega$. By definition, $\rho$ is an $A$-run on $v^\omega$ such that:
	\begin{equation*}
		\max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; \pi(\rho[j]) = k \} = \max \{ k \mid \forall i \in \N,\; \exists j \geq i,\; n_j = k \}
	\end{equation*}
	Therefore, we have: $\msf{Priorities}_A(\msf{sem}_A(\overline{v})) \subseteq \msf{Priorities}_A(v)$. We obtain the desired equality.

	Therefore, for all $\overline{v},\overline{v}' \in \msf{Fm}_{\msf{PW}(\Sigma)}$ such that $\msf{sem}_A(\overline{v}) = \msf{sem}_A(\overline{v}')$, we have $\msf{Priorities}_A(v) = \msf{Priorities}_A(v')$, and thus $A\models \overline{v}$ if and only if $A\models \overline{v}'$. Therefore, the $(\msf{PW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ captures the $\msf{PW}(\Sigma)$-semantics. In fact, the $(\msf{PW}(\Sigma),A)$-pair $(\msf{SEM}_A,\msf{sem}_A)$ inductively captures the $\msf{PW}(\Sigma)$-semantics. Therefore, by Theorem~\ref{thm:size_separation}, for all $\mathcal{PA}(\Sigma)$-samples $\mathcal{S} = (\mathcal{P},\mathcal{N})$, if there is a $\msf{PW}(\Sigma)$-formula that is $\mathcal{S}$-separating, there is one of size at most:
	\begin{equation*}
		\prod_{A \in \mathcal{S}} |\msf{SEM}_{A}| = \prod_{A \in \mathcal{S}} |\{ Q_A \to 2^{Q_A \times \pi(Q)}| = \prod_{A \in \mathcal{S}} (2^{|Q_A| \times n_A})^{|Q_A|} = 2^{\sum_{A \in \mathcal{S}} |Q_A|^2 \cdot n_A}
	\end{equation*}
\end{proof}

Let us now use this lemma to establish Corollary~\ref{coro:parity_automaton}.
Let us now use this lemma to establish Corollary~\ref{coro:parity_automaton}.
\begin{proof}[Proof of Corollary~\ref{coro:parity_automaton}]
	Consider a pair $(\mathcal{P},\mathcal{N})$ of finite sets of parity automata, and assume that there exists an ultimately periodic word $u \cdot v^\omega \in \Sigma^{\omega}$ accepted by all automata in $\mathcal{P}$ and rejected by all automata in $\mathcal{N}$. For all $A \in \mathcal{P} \cup \mathcal{N}$, we denote $A$ by $(Q_A,\Sigma,I_A,\delta_A,\pi_A)$, and:
	\begin{itemize}
		\item We define the subset of states $I_{A'} \subseteq Q_A$ as follows:
		\begin{itemize}
			\item If $A \in \mathcal{P}$, we consider some state $q_A \in Q_A$ such that: there exists a finite $A$-run $\rho$ on $u$ such that $\head{\rho} = q_A$, and there exists an infinite $A$-run $\rho'$ on $v^\omega$ starting in $q_A$ whose maximum integer seen infinitely often is even. We let $I_{A'} := \{q_A\}$.
			\item If $A \in \mathcal{N}$, we let:
			\begin{equation*}
				I_{A'} := \{ q \in Q \mid v^\omega\text{ is not accepted by the parity automaton }(Q_A,\Sigma,\{q\},\delta_A,\pi_A) \}
			\end{equation*}
		\end{itemize}
		\item We define the parity automaton:
		\begin{align*}
			A' := (Q_A,\Sigma,I_A',\delta_A,\pi_A) \in \mathcal{PA}(\Sigma)
		\end{align*}
		\item We define the finite automaton:
		\begin{align*}
			A_u :=
			\begin{cases}
				(Q_A,\Sigma,I_A,\delta_A,I_A') \in \mathcal{FA}(\Sigma) & \text{ if } A \in \mathcal{P} \\
				(Q_A,\Sigma,I_A,\delta_A,Q \setminus I_A') \in \mathcal{FA}(\Sigma) & \text{ if } A \in \mathcal{N} \\
			\end{cases}
		\end{align*}
	\end{itemize}
	Now, we let $\mathcal{P}' := \{ A' \mid A \in \mathcal{P} \}$ and $\mathcal{N}' := \{ A' \mid A \in \mathcal{N} \}$. Then, we have that the periodic word $v^\omega \in \Sigma^{\omega}$ is accepted by all automata in $\mathcal{P}'$ and rejected by all automata in $\mathcal{N}'$.	By Lemma~\ref{lem:logic_periodic_words}, the $\msf{PW}(\Sigma)$-formula $\overline{v} \in \msf{Fm}_{\msf{PW}(\Sigma)}$ is such that, for all $A' \in \mathcal{P}'$, we have $A' \models \overline{v}$, and for all $A' \in \mathcal{N}'$, we have $A' \not\models \overline{v}$. %Thus, the sample $\mathcal{S}' = (\mathcal{P}',\mathcal{N}')$ is a positive instance of the decision problem $\msf{PvLn}(\msf{PW}(\Sigma),\mathcal{PA}(\Sigma))$. 
	Hence, by Lemma~\ref{lem:periodic_words_logic}, there is some $\msf{PW}(\Sigma)$-formula $\overline{v'}$, for some $v' \in \Sigma^+$, that is $\mathcal{S}'$-separating and of size at most $2^{k}$, with $k := \sum_{A' \in \mathcal{S}} |Q_{A'}|^2 \cdot n_{A'} = \sum_{A \in \mathcal{S}} |Q_{A}|^2 \cdot n_{A}$. By Lemma~\ref{lem:logic_periodic_words}, the word $(v')^\omega \in \Sigma^\omega$ is accepted by all the automata in $\mathcal{P}'$, rejected by all the automata in $\mathcal{N}'$. 

	Furthermore, we let $\mathcal{P}_u := \{ A_u \mid A \in \mathcal{P} \}$ and $\mathcal{N}_u := \{ A_u \mid A \in \mathcal{N} \}$. Consider some automaton $A \in \mathcal{P} \cup \mathcal{N}$. Since the ultimately periodic word $u \cdot v^\omega$ is accepted by $A$ if and only if $A \in \mathcal{P}$, it follows that the finite word $u$ is accepted by $A_u$ if and only if $A \in \mathcal{P}$. Thus, by Corollary~\ref{coro:finite_automaton}, we have that there is a word $u' \in \Sigma^*$ that is accepted by all the finite automata in $\mathcal{P}_u$ and rejected by all the finite automata in $\mathcal{N}_u$, and of size at most $2^{n}-1$, for $n := \sum_{A \in \mathcal{S}} |Q_{A}|$. 

	Consider now the ultimately periodic word $w' := u' \cdot (v')^\omega$. We have $|w'| \leq 2^{n} + 2^{k} - 1$. Furthermore, for all $A \in \mathcal{P} \cup \mathcal{N}$:
	\begin{itemize}
		\item If $A \in \mathcal{P}$, then there exists a finite $A$-run $\rho$ on $u'$ such that $\head{\rho} = q_A$, since $u'$ is accepted by $A_u$. Furthermore, there is an infinite $A$-run on $(v')^\omega$, starting at $q_A$, whose maximum integer seen infinitely often is even, since $(v')^\omega$ is accepted by $A'$. Thus, the word $w'$ is accepted by $A$.
		\item If $A \in \mathcal{N}$, then all finite $A$-runs $\rho$ on $u'$ are such that $\head{\rho} \in I_A'$, since $u'$ is rejected by $A_u$. Furthermore, all infinite $A$-runs on $(v')^\omega$, starting from any state in $I_A'$, are with a maximum integer seen infinitely often odd, since $(v')^\omega$ is rejected by $A'$. Thus, the word $w'$ is rejected by $A$.
	\end{itemize}
	Overall, the word $w'$ is accepted by all the parity automata in $\mathcal{P}$, rejected by all the parity automata in $\mathcal{N}$, and such that $|w'| \leq 2^{n} + 2^{k} - 1$.
\end{proof}		

\section{Proof of Proposition~\ref{prop:lower_bound_ltl}}
\label{proof:lower_bound_ltl}
Let us first define below the samples, parameterized by an integer $n \in \N$, that we will consider to establish Proposition~\ref{prop:lower_bound_ltl}. %On the way, we also introduce again the notations used in the proof sketch given in the main part of the paper.
\begin{definition}
	\label{def:samples_ltl_lower_bound}
	For all $n \geq 1$, we let $p_n \in \N$ denote the $n$-th prime number, thus $p_1 = 2$, $p_2 = 3$, etc. Note that we have $\sum_{l = 1}^j p_{l} \sim (j^2)/(2 \cdot \log j)$, while $\prod_{l = 1}^j p_{l} = e^{(1 + o(1)) \cdot j \cdot \log j}$ \cite[VII.27,VII.35]{sandor2004handbook}.

	Furthermore, consider some $x \neq y \in \prop$. For all $n \in \N$, we let $w_n(x) := (\{y\} \cdot \{y\} \cdots \{y\} \cdot \{x\})^\omega \in \mathcal{IW}(\prop)$ be such that $|w_n| = n$. 

	Consider now some $n,j \in \N$. We let: 
	\begin{itemize}
		\item $\mathcal{P}_n^j(x) := \{ w_{p_i}(x)[j:] \mid i \in \Interval{1,n}\} \cup \{ w_4'(x)[j:] \}$ with $w_4'(x) := \{y\} \cdot \{x\} \cdot w_4(x)$;
		\item $\mathcal{N}_n^j(x) := \{w_4(x)[j:]\}$
	\end{itemize}
	We also let $\mathcal{S}^{\wedge,j}_n(x) := (\mathcal{P}_n^j(x),\mathcal{N}_n^j(x))$ and $\mathcal{S}^{\lor,j}_n(s) := (\mathcal{N}_n^j(x),\mathcal{P}_n^j(x))$.
	%
	%We also let $\msf{Sync}_n(a) := \min \{ j \in \N \mid \forall w \in \mathcal{P}_n^j(a),\; a \in w[0] \}$.
\end{definition}

Let us first establish a few simple properties that the above definition satisfies.
\begin{lemma}
	\label{lem:lower_bound_ltl_sample_works_first}
	Consider some $x \neq y \in \prop$. Let $n \in \N$. 
	\begin{itemize}
		\item The least integer $k_n \in \N$ such that for all $w \in \mathcal{P}_n^{k_n}(x)$, we have $x \in w[0]$ and for all $w \in \mathcal{N}_n^{k_n}(x)$, we have $x \notin w[0]$ is equal to $k_n := \prod_{j = 1}^n p_j - 1$.  
		\item For all $j \in \N$, if $y \notin w_4(x)[j]$, then $y \notin w_2(x)[j]$.
	\end{itemize}
\end{lemma}
\begin{proof}
	By definition, for all $j \in \N$, we have $w_n(x)[j] = \{x\}$ if $n \mid j+1$ (i.e $n$ is a divisor of $j+1$) and $w_n(x)[j] = \{y\}$ otherwise. Hence, we have:
	\begin{equation*}
		\forall l \in \Interval{1,n},\; x \in w_{p_l}[j] \Longleftrightarrow \forall l \in \Interval{1,n},\; p_l \mid j+1 \Longleftrightarrow \prod_{l = 1}^n \; p_l \mid j+1
	\end{equation*} 
	Hence, for all $j \in \N$ such that for all $w \in \mathcal{P}_n^{k_n}(x)$, we have $x \in w[j]$, we have, for all $l \in \Interval{1,n}$, $x \in (w_{p_l}[j:])[0] = w_{p_l}[j]$, and thus $j+1 \geq \prod_{l = 1}^n \; p_l$, i.e. $j \geq k_n$. Furthermore, for all $j \in \N$, we have $x \in (\{y\} \cdot \{x\} \cdot w_4)^\omega[j]$ if and only if $j+1 \mod 4 = 2$. In addition, since $k_n+1$ is even and not divisible by 4, it follows that $x \in  w_4'[k_n]$; and similarly $x \notin w_4[k_n]$. 

	On the other hand, for all $j \in \N$, if $y \notin w_4(x)[j]$, then $x \in w_4(x)[j]$, and $4 \mid j+1$, thus $2 \mid j+1$ and $x \in w_2(x)[j]$, hence $y \notin w_2(x)[j]$.
\end{proof}

The above definition satisfies another property, a little harder to establish, that is crucial to the proof of Proposition~\ref{prop:lower_bound_ltl}.
\begin{lemma}
	\label{lem:lower_bound_ltl_sample_works_second}
	Consider a monotone fragment $\msf{L}$ of $\LTL(\prop)$ with $\vee \notin \msf{Op}$%that disallows the operator $\lor$
	. Consider also some $x \neq y \in \prop$. Let $n \in \N$ and $j < k_n \in \N$. Assume that there exists an $\msf{L}$-formula $\varphi$ that is $\mathcal{S}^{\wedge,j}_n(x)$-separating. In that case, there is a sub-formula $\psi \in \msf{Sub}(\varphi)$ such that:
	\begin{itemize}
		\item $\msf{sz}(\varphi) \geq \msf{sz}(\psi) + 1$;
		\item the $\msf{L}$-formula $\psi$ is $\mathcal{S}^{\wedge,j+1}_n(x)$-separating.
	\end{itemize}
\end{lemma}
\begin{proof}
	Let us prove the result by exhaustion:
	\begin{itemize}
		%\item Assume that $\varphi \in \{\top,\bot\}$. Then, it cannot be $\mathcal{S}^{\wedge,j}_n(x)$-separating.
		\item Assume that $\varphi \in \{p,\bar{p}\}$. Then, since $j < k_n$ and by Lemma~\ref{lem:lower_bound_ltl_sample_works_first}, we have that $\varphi$ cannot possibly be $\mathcal{S}^{\wedge,j}_n(x)$-separating (the case $\varphi = x$ follows from the first item, the case $\varphi = y$ follows from the second one).
		\item Assume that $\varphi = \varphi_1 \wedge \varphi_2$. Then, let $\psi \in \{\varphi_1,\varphi_2\}$ be an $\msf{L}$-formula such that $w_4(j)[:] \not\models \psi$. Then, we have $\msf{sz}(\psi) < \msf{sz}(\varphi)$ and $\psi$ is $\mathcal{S}_n^{\wedge,j}(x)$-separating. Thus, we can apply (by induction) the  argument to the formula $\psi$ to obtain an $\msf{L}$-formula $\psi' \in \msf{Sub}(\psi) \subseteq \msf{Sub}(\varphi)$ satisfying the assumptions of the lemma.
		\item Assume that $\varphi = \lX \varphi'$. Then, by definition, we have $\msf{sz}(\varphi') < \msf{sz}(\varphi)$ and $\varphi'$ is $\mathcal{S}_n^{\wedge,j+1}(x)$-separating.
		\item Assume that $\varphi = \lF \varphi'$ or $\varphi = \lG \varphi'$. Since $\{ (w_4(x)[j:])[k:] \mid k \in \N \} = \{ (w_4'(x)[j:])[k:] \mid k \in \N \}$, it follows that either $\varphi$ accepts reject both $w_4'(x)[j:]$ and $w_4(x)[j:]$ or rejects both $w_4'(x)[j:]$ and $w_4(x)[j:]$, thus it is not $\mathcal{S}_n^{\wedge,j}(x)$ separating.
	\end{itemize}
	Overall, whenever $\varphi$ is $\mathcal{S}_n^{\wedge,j}(x)$-separating, it is possible to extract a sub-formula $\psi \in \msf{Sub}(\varphi)$ satisfying the conditions of the lemma.
\end{proof}

Finally, let us prove a final lemma before we proceed to the proof of Proposition~\ref{prop:lower_bound_ltl}. This lemma states that the functions defined below behave like negations. 
\begin{definition}
	For all $* \in \{\wedge,\lor\}$, we denote by $\LTL_{*}(\prop)$ the $\LTL(\prop)$-monotone fragment that allows exactly the $\LTL$-operators $\{p,\bar{p},*,\lX,\lF,\lG\}$. 

	For all $* \neq *' \in \{\wedge,\lor\}$, we define by induction the function $f^{\neg}_{* \to *'}: \msf{Fm}_{\LTL_{*}(\prop)} \rightarrow \msf{Fm}_{\LTL_{*'}(\prop)}$ such that:
	\begin{align*}
		f^{\neg}_{* \to *'}(p) & := \bar{p} \\
		f^{\neg}_{* \to *'}(\bar{p}) & := p \\
		f^{\neg}_{* \to *'}(\varphi_1 * \varphi_2) & := f^{\neg}_{* \to *'}(\varphi_1) *' f^{\neg}_{* \to *'}(\varphi_2) \\
		f^{\neg}_{* \to *'}(\lX \varphi) & := \lX f^{\neg}_{* \to *'}(\varphi) \\
		f^{\neg}_{* \to *'}(\lF \varphi) & := \lG f^{\neg}_{* \to *'}(\varphi) \\
		f^{\neg}_{* \to *'}(\lG \varphi) & := \lF f^{\neg}_{* \to *'}(\varphi) 
	\end{align*}
\end{definition}
\begin{lemma}
	\label{lem:ltl_function_neg}
	Consider some $x \neq y \in \prop$ and any word $w \in \cup_{n,j \in \N} \; \mathcal{S}_n^j(x)$. For all $* \neq *' \in \{\wedge,\lor\}$ and $\LTL_{*}(\prop)$-formulas $\varphi$, we have $\msf{sz}(\varphi) = \msf{sz}(f^{\neg}_{* \to *'}(\varphi))$ and:
	\begin{equation*}
		w \models \varphi \Longleftrightarrow w \not\models f^{\neg}_{* \to *'}(\varphi)
	\end{equation*} 
\end{lemma}
\begin{proof}
	The size equality can be proved straightforwardly by induction. Then, the word $w \in (2^\prop)^\omega$ is such that, for all $i \in \N$, we have $p \in w[i]$ if and only if $\bar{p} \notin w[i]$. The result of the lemma then follows from the classical $\LTL$-equivalences recalled below. For all $\LTL(\prop)$-formulas $\varphi,\varphi_1,\varphi_2$ and word $w \in (2^\prop)^\omega$, we have: 
	\begin{align*}
		w \not\models \lX \varphi & \Longleftrightarrow w \models \lX \neg \varphi \\ 
		%w \not\models \lF \varphi & \Longleftrightarrow w \models \lG \neg \varphi \\ 
		w \not\models \lG \varphi & \Longleftrightarrow w \models \lF \neg \varphi \\ 
		w \not\models \varphi_1 \wedge \varphi_2 & \Longleftrightarrow w \models \neg \varphi_1 \vee \neg \varphi_2 
		%w \not\models \varphi_1 \vee \varphi_2 & \Longleftrightarrow w \models \neg \varphi_1 \wedge \neg \varphi_2 \\ 
	\end{align*}
\end{proof}

We can now proceed to the proof of Proposition~\ref{prop:lower_bound_ltl}.
\begin{proof}
	Consider some $x \neq y \in \prop$. Consider some $i \in \N$. We let $t_i := \sum_{w \in \mathcal{S}_i^{\wedge,0}(x)} |w| = \sum_{l=1}^i p_i + 10$. Since $\sum_{l=1}^i p_i \sim (i^2)/(2\cdot \log i)$, it follows that there is some $n_0 \in \N$ such that, for all $i \geq n_0$, we have $t_i \leq i^2$. Furthermore, since we have $k_i + 1 = \prod_{l=1}^i p_i = e^{(1 + o(1)) \cdot i \cdot \log i}$, if follows that there is some $n_0' \in \N$ such that, for all $i \geq n_o'$, we have $k_i + 1 \geq 2^{i}$. Let $n_1 := \max(n_0,n_0')$. 

	Consider now any monotone $\LTL(\prop)$-fragment $\msf{L}$ such that $\vee \notin \msf{Op}$. Let $x \neq y \in \prop$ be such that $x \in \msf{Op}$. Consider any  $n \in \N$, and let $i := \max(n,n_1)$ and $\mathcal{S} := \mathcal{S}_{i}^{\wedge,0}(x)$. Let us show that the minimal size of an $\msf{L}$-formula that is $\mathcal{S}$-separating is $k_i+1$. Since we have $i \leq t_i \leq i^2$ and $k_i + 1 \geq 2^{i} \geq 2^{\sqrt{t_i}}$, this will show the result for monotone fragments without $\vee$. 

	First of all, consider the $\msf{L}$-formula $\varphi := (\lX)^{k_i} x$ of size $\msf{sz}(\varphi) = k_i + 1$. By Lemma~\ref{lem:lower_bound_ltl_sample_works_first}, it is $\mathcal{S}$-separating.

	Consider now any $\mathcal{S}$-separating $\msf{L}$-formula $\varphi$. By iteratively applying Lemma~\ref{lem:lower_bound_ltl_sample_works_second} to $j \in \Interval{0,k_i-1}$, we obtain that there is some $\msf{L}$-formula $\psi \in \msf{Sub}(\varphi)$ such that $\msf{sz}(\varphi) \geq \msf{sz}(\psi) + k_i$ (and $\psi$ is $\mathcal{S}_i^{\wedge,k_i}$-separating). Since $\msf{sz}(\psi) \geq 1$, it follows that $\msf{sz}(\varphi) \geq k_i+1$. 

	Let us now consider a monotone $\LTL(\prop)$-fragment $\msf{L}$ such that $\vee \in \msf{Op}$, and thus $\wedge \notin \msf{Op}$. Let $x \neq y \in \prop$ be such that $x \in \msf{Op}$. Consider any $n \in \N$, and let $i := \max(n,n_1)$ and $\mathcal{S} := \mathcal{S}_{i}^{\vee,0}(y)$. First, the $\msf{L}$-formula $\varphi := (\lX)^{k_i} x$ of size $\msf{sz}(\varphi) = k_i + 1$ is $\mathcal{S}$-separating by Lemma~\ref{lem:lower_bound_ltl_sample_works_first}. Furthermore, for all $\msf{L}$-formulas $\varphi$, by Lemma~\ref{lem:ltl_function_neg}, we have $\varphi \in \msf{Fm}_{\LTL_{\vee}(\prop)}$, $f^{\neg}_{\vee \to \wedge}(\varphi) \in \msf{Fm}_{\LTL_{\wedge}(\prop)}$, and $\msf{sz}(\varphi) = \msf{sz}(f^{\neg}_{\vee \to \wedge}(\varphi))$. Consider any $\msf{L}$-formula $\varphi$ that is $\mathcal{S}$-separating. We have that the $\LTL_{\wedge}(\prop)$-formula $f^{\neg}_{\vee \to \wedge}(\varphi)$ is $\mathcal{S}_{i}^{\wedge,0}(y)$, and thus of size at least $k_i + 1$ (as showed above). Hence, $\varphi$ is also of size at least $k_i + 1$. The proposition follows.
\end{proof}

\section{Proof of Proposition~\ref{prop:lower_bound_ml}}
\label{proof:lower_bound_ml}
In all of this section, we consider the size-5 alphabet $\Sigma := \{a,b,c,d,e\}$ and the same size-5 set of actions $\act := \Sigma$. Furthermore, for all $\alpha \in \act$, we denote the operator $\langle \alpha \rangle^{\geq 1}$ simply by $\langle \alpha \rangle$. We first define below the samples, parameterized by an integer $n \in \N$, that we will consider to establish Proposition~\ref{prop:lower_bound_ml}. 
\begin{definition}
	\label{def:samples_ml_lower_bound}
	For all $n \in \N$, we let $A_n = (Q_n,\Sigma,I_n,\delta_n,F_n)$ denote the finite automaton of Theorem~\ref{thm:automtaton_least_word_exponential}. For all $Z \subseteq Q_n$, and $\alpha \in \Sigma$, we let $\delta(Z,\alpha) := \cup_{q \in Z} \delta(q,\alpha)$. Then, we define inductively on words $u \in \Sigma^*$ the set of states $\delta_n^*(Z,u) \subseteq Q_n$ to which there is $u$-labeled path from some state in $Z$. Formally:
	\begin{align*}
		\delta_n^*(Z,\varepsilon) & := Z \subseteq Q_n\\
		\forall u \in \Sigma^*,\; \alpha \in \Sigma,\; \delta_n^*(Z,u \cdot \alpha) & := \delta(\delta_n^*(Z,u),\alpha) \subseteq Q_n
	\end{align*}

	For all $Z \subseteq Q_n$ and $P \subseteq \{p\}$, we let $K_n^Z(P) \in \mathcal{K}(\prop,\act)$ denote the Kripke structure $K_n^Z(P) = (Q_n,Z,\act,\delta_n,\prop,\pi_{n}^P)$ mimicking the automaton $A_n$ with $Z$ as set of initial states, and such that for all $q \in Q_n$, we have:
	\begin{align*}
		\pi_{n}^P(q) := \begin{cases}
			\{p\} \setminus P & \text{ if }q \in Q_n \setminus F_n\\
			P & \text{ if }q \in F_n
		\end{cases}
	\end{align*}
	We also let $K(P) := (\{q^{\msf{idle}},q_n^{\msf{win}}\},\{q^{\msf{idle}}\},\act,\delta,\prop,\pi^P)$ be such that:
	\begin{itemize}
		\item For all $\alpha \in \act$:
		\begin{align*}
			\delta(q^{\msf{idle}},\alpha) & := \{q^{\msf{idle}},q^{\msf{loop}}\} \\
			\delta(q^{\msf{loop}},\alpha) & := \{q_n^{\msf{win}}\}
		\end{align*}
		\item For all $q \in Q_n'$:
		\begin{align*}
			\pi^P(q^{\msf{idle}}) & := P \\
			\pi^P(q^{\msf{loop}}) & := \{p\} \setminus P
		\end{align*}
	\end{itemize}

	Consider now some $n \in \N$ and $Z \subseteq Q_n$. We let: $\mathcal{S}^{Z,[\cdot]}_n := (\{K_n^Z(\emptyset)\},\{K(\emptyset)\})$ and $\mathcal{S}^{Z,\langle\cdot\rangle}_n := (\{K(\{p\})\},\{K_n^{q}(\{p\}) \mid q \in Z\})$.

	\iffalse
	%For all $P_1.P_2 \subseteq \{p\}$, f
	For all $Z \subseteq Q_n$, we let $K_n^Z \in \mathcal{K}(\prop,\act)$ denote the Kripke structure $K_n^Z(P_1,P_2) = (Q_n,Z,\act,\delta_n,\prop,\pi_{n}^{(P_1,P_2)})$ mimicking the automaton $A_n$ with $Z$ as set of initial states, and such that for all $q \in Q_n$, we have:
	\begin{align*}
		\pi_{n}^{(P_1,P_2)}(q) := \begin{cases}
			P_1 & \text{ if }q \in Q_n \setminus F_n\\
			P_2 & \text{ if }q \in F_n
		\end{cases}
	\end{align*}
	We also let $K(P_1,P_2) := (\{q^{\msf{idle}},q_n^{\msf{win}}\},\{q^{\msf{idle}}\},\act,\delta,\prop,\pi^{(P_1,P_2)})$ be such that:
	\begin{itemize}
		\item For all $\alpha \in \act$:
		\begin{align*}
			\delta(q^{\msf{idle}},\alpha) & := \{q^{\msf{idle}},q^{\msf{loop}}\} \\
			\delta(q^{\msf{loop}},\alpha) & := \{q_n^{\msf{win}}\}
		\end{align*}
		\item For all $q \in Q_n'$:
		\begin{align*}
			\pi^{(P_1,P_2)}(q^{\msf{idle}}) & := P_2 \\
			\pi^{(P_1,P_2)}(q^{\msf{loop}}) & := P_1
		\end{align*}
	\end{itemize}

	Consider now some $n \in \N$ and $Z \subseteq Q_n$. We let: $\mathcal{S}^{Z,[\cdot]}_n := (\mathcal{P}_n^Z(\{p\},\emptyset),\mathcal{N}_n(\{p\},\emptyset))$, and $\mathcal{S}^{Z,\langle\cdot\rangle}_n := (\mathcal{N}_n(\emptyset,\{p\}),\mathcal{P}_n^Z(\emptyset,\{p\}))$.
	%\begin{itemize}
	%	\item $\mathcal{P}_n^Z(x) := \{ K_n^Z(x) \}$;
	%	\item $\mathcal{N}_n(x) := \{ K(x) \}$;
	%	\item $\mathcal{S}^{Z,[\cdot]}_n(x) := (\mathcal{P}_n^Z(x),\mathcal{N}_n(x))$, and $\mathcal{S}^{Z,\langle\cdot\rangle}_n(x) := (\mathcal{N}_n(x),\mathcal{P}_n^Z(x))$.
	%\end{itemize}
	\fi
\end{definition}

This definition of $\mathcal{S}^{Z,[\cdot]}_n$ satisfies the lemma below.
\begin{lemma}
	\label{lem:lower_bound_ml_sample_works}
	Consider an $\ML(\prop,\act)$-fragment $\msf{L}$ such that such that $\vee,\neg \notin \msf{Op}$. Let $n \in \N$, and $Z \subseteq Q_n$ such that $Z \cap F_n \neq \emptyset$. Assume that there exists an $\msf{L}$-formula $\varphi$ that is $\mathcal{S}^{Z,[\cdot]}_n$-separating. In that case, there is a sub-formula $\psi \in \msf{Sub}(\varphi)$ and some $\alpha \in \Sigma$ such that:
	\begin{itemize}
		\item $\msf{sz}(\varphi) \geq \msf{sz}(\psi) + 1$;
		\item the $\msf{L}$-formula $\psi$ is $\mathcal{S}^{\delta(Z,\alpha),[\cdot]}_n$-separating.
	\end{itemize}
\end{lemma}
\begin{proof}
	Let us prove the result by exhaustion:
	\begin{itemize}
		%\item Assume that $\varphi \in \{\top,\bot\}$. Then, it cannot be $\mathcal{S}^{Z,[\cdot]}_n(x)$-separating.
		\item Assume that $\varphi = p$. Since $Z \cap F_n \neq \emptyset$, an initial state of $K_n^Z(\emptyset)$ is labeled by $\emptyset$, hence $p \not\models K_n^Z(\emptyset)$, which is a positive model.
		\item Assume that $\varphi = \varphi_1 \wedge \varphi_2$. Then, let $\psi \in \{\varphi_1,\varphi_2\}$ be an $\msf{L}$-formula such that $K(\emptyset) \not\models \psi$. Then, we have $\msf{sz}(\psi) < \msf{sz}(\varphi)$ and $\psi$ is $\mathcal{S}_n^{Z,[\cdot]}$-separating. Thus, we can apply (by induction) the  argument to the formula $\psi$ to obtain an $\msf{L}$-formula $\psi' \in \msf{Sub}(\psi) \subseteq \msf{Sub}(\varphi)$ satisfying the assumptions of the lemma.
		\item Assume that $\varphi = \langle \alpha \rangle \varphi'$ for some $\alpha \in \act$.
		Since the initial state $q^{\msf{idle}}$ of the Kripke structure $K(\emptyset)$ has as $\alpha$-successor the state $q^{\msf{loop}}$ labeled by $\{p\}$, which is thus satisfied by all $\msf{L}$-formulas, it follows that the formula $\varphi$ cannot reject $K(\emptyset)$.
		\item Assume that $\varphi = [\alpha] \varphi'$ for some $\alpha \in \act$. As mentioned above, the state $q^{\msf{loop}}$ in the Kripke structure $K(\emptyset)$ is satisfied by all $\msf{L}$-formulas. Furthermore, we have $\delta(q^{\msf{idle}},\alpha) = \{q^{\msf{idle}},q^{\msf{loop}}\}$. It follows that $q^{\msf{idle}} \not\models \varphi'$. In addition, for all $q \in Z$, since $q \models \varphi$, for all $q' \in \delta(q,\alpha)$, we have $q' \models \varphi'$. Therefore, the $\msf{L}$-formula $\varphi'$ is  $\mathcal{S}^{\delta(Z,\alpha),[\cdot]}_n$-separating and such that $\msf{sz}(\varphi') + 1 = \msf{sz}(\varphi)$.
	\end{itemize}
	Overall, whenever $\varphi$ is $\mathcal{S}_n^{Z,[\cdot]}$-separating, it is possible to extract a sub-formula $\psi \in \msf{Sub}(\varphi)$ satisfying the conditions of the lemma.		
\end{proof}

In a somewhat symmetrical manner, we prove the result below about the sample $\mathcal{S}^{Z,\langle\cdot\rangle}_n$.
\begin{lemma}
	\label{lem:lower_bound_ml_sample_works_vee}
	Consider an $\ML(\prop,\act)$-fragment $\msf{L}$ such that $\wedge,\lnot \notin \msf{Op}$. Let $n \in \N$, and $Z \subseteq Q_n$ such that $Z \cap F_n \neq \emptyset$. Assume that there exists an $\msf{L}$-formula $\varphi$ that is $\mathcal{S}^{Z,\langle\cdot\rangle}_n$-separating. In that case, there is a sub-formula $\psi \in \msf{Sub}(\varphi)$ and some $\alpha \in \Sigma$ such that:
	\begin{itemize}
		\item $\msf{sz}(\varphi) \geq \msf{sz}(\psi) + 1$;
		\item the $\msf{L}$-formula $\psi$ is $\mathcal{S}^{\delta(Z,\alpha),\langle\cdot\rangle}_n$-separating.
	\end{itemize}
\end{lemma}
\begin{proof}
	Let us prove the result by exhaustion:
	\begin{itemize}
		\item Assume that $\varphi = p$. Since there is some $q \in Z \cap F_n$, it follows that the initial state of $K_n^{\{q\},\langle\cdot\rangle}(\{p\})$ is labeled by $p$, hence $p \models K_n^{\{q\},\langle\cdot\rangle}(\{p\})$, which is a negative model.
		\item Assume that $\varphi = \varphi_1 \vee \varphi_2$. Then, let $\psi \in \{\varphi_1,\varphi_2\}$ be an $\msf{L}$-formula such that $K(\{p\}) \models \psi$. Then, we have $\msf{sz}(\psi) < \msf{sz}(\varphi)$ and $\psi$ is $\mathcal{S}_n^{Z,\langle\cdot\rangle}$-separating. Thus, we can apply (by induction) the  argument to the formula $\psi$ to obtain an $\msf{L}$-formula $\psi' \in \msf{Sub}(\psi) \subseteq \msf{Sub}(\varphi)$ satisfying the assumptions of the lemma.
		\item Assume that $\varphi = \langle \alpha \rangle \varphi'$ for some $\alpha \in \act$. Since $\pi^{\{p\}}(q^{\msf{loop}}) = \emptyset$ and $\delta(q^{\msf{loop}},\alpha') = \{q^{\msf{loop}}\}$ for all $\alpha' \in \act$, it follows that no $\msf{L}$-formula satisfies the state $q^{\msf{loop}}$. Hence, since $\delta(q^{\msf{idle}},\alpha) = \{q^{\msf{idle}},q^{\msf{loop}}\}$, it follows that $q^{\msf{idle}} \models \varphi'$. In addition, for all $q \in Z$, in the Kripke structure $K_n^{\{q\},\langle\cdot\rangle}(\{p\})$, since $q \not\models \varphi$, for all $q' \in \delta(q,\alpha)$, we have $q' \not\models \varphi'$. Therefore, the $\msf{L}$-formula $\varphi'$ is  $\mathcal{S}^{\delta(Z,\alpha),\langle\cdot\rangle}_n$-separating and such that $\msf{sz}(\varphi') + 1 = \msf{sz}(\varphi)$.
		\item Assume that $\varphi = [\alpha] \varphi'$ for some $\alpha \in \act$. As mentioned above, the state $q^{\msf{loop}}$ in the Kripke structure $K(\{p\})$ is not satisfied by any $\msf{L}$-formula. Furthermore, we have $\delta(q^{\msf{idle}},\alpha) = \{q^{\msf{idle}},q^{\msf{loop}}\}$. It follows that the formula $\varphi$ cannot accept the structure $K(\emptyset)$.
	\end{itemize}
	Overall, whenever $\varphi$ is $\mathcal{S}_n^{Z,\langle\cdot\rangle}$-separating, it is possible to extract a sub-formula $\psi \in \msf{Sub}(\varphi)$ satisfying the conditions of the lemma.		
\end{proof}

Let us now proceed to the proof of Proposition~\ref{prop:lower_bound_ml}.
\begin{proof}
	Consider some $i \in \N$. We let $t_i := \sum_{K \in \mathcal{S}_i^{I_i,[\cdot]}} |Q_K| = \sum_{K \in \mathcal{S}_i^{I_i,\langle\cdot\rangle}} |Q_K| = 25i+113$ (since $I_i$ is a singleton). Let $n_0 \in \N$ be such that, for all $i \geq n_0$, we have $x_i := (2^i-1)\cdot (i+1) +1 \geq 2^{i+113/25}$.  

	Consider any $n \in \N$, and let $i := \max(n,n_0)$. Assume that $\vee \notin \msf{Op}'$ (resp. $\wedge \notin \msf{Op}'$). Let $\mathcal{S} := \mathcal{S}_i^{I_i,[\cdot]}(x)$ (resp. $\mathcal{S} := \mathcal{S}_i^{I_i,\langle\cdot\rangle}(x)$). Let us show that the minimal size of an $\msf{L}'$-formula that is $\mathcal{S}$-separating is $x_i+1$. Since we have $i \leq t_i = 25i+113$ and $x_i \geq 2^{t_i/25}$, the result follows.

	By Theorem~\ref{thm:automtaton_least_word_exponential}, the least size of a word $u_i = u_i^0 \cdots u_i^k \in \Sigma^*$ such that $\delta^*(I_i,u_i) \subseteq Q_i \setminus F_i$ is $k+1 = x_i$. Now, consider the $\msf{L}'$-formula $\varphi := [u_i^0] [u_i^1] \cdots [u_i^k] p$ (resp. $\varphi := \langle u_i^0\rangle \langle u_i^1\rangle \cdots \langle u_i^k\rangle p$) of size $\msf{sz}(\varphi) = |u_i| +1 = x_i + 1$. By definition of $\mathcal{S}$, this formula is $\mathcal{S}$-separating. 

	Consider now any $\mathcal{S}$-separating $\msf{L}'$-formula $\varphi$. By iteratively applying Lemma~\ref{lem:lower_bound_ml_sample_works} (resp. Lemma~\ref{lem:lower_bound_ml_sample_works_vee}), we obtain that there is some $\msf{L}'$-formula $\psi \in \msf{Sub}(\varphi)$ and a word $u \in \Sigma^*$ such that $\delta^*(I_i,u) \subseteq Q_i \setminus F_i$ and $\msf{sz}(\varphi) \geq \msf{sz}(\psi) + |u|$% (and $\psi$ is $\mathcal{S}_i^{\delta(I_i,u)}$-separating)
	. Since $\msf{sz}(\psi) \geq 1$, and by Theorem~\ref{thm:automtaton_least_word_exponential}, it follows that $\msf{sz}(\varphi) \geq x_i+1$. The result follows.
\end{proof}

