\begin{align*}
(\langle e_1 e_2 \mid s, n \rangle, w) & \to  (\langle e_1 \mid s_e, n \rangle \langle e_2 \mid s_o, n \rangle , w) 
% \hspace{2em}
\\ 
(\langle \lambda x^\tau \ldot e_1 \mid s, n \rangle, w) & \to  (\lambda x^\tau \ldot \langle  e_1 \mid s, n \rangle, w)
\\
