\section*{Appendix D: Mathematical Background}
\addcontentsline{toc}{section}{Appendix: Mathematical Background}

\subsection*{Overview}
In this appendix, we collect and summarize the principal mathematical concepts, definitions, and results that underpin the main text. The goal is to provide a concise but self‐contained exposition of the background material required to follow the formal arguments and proofs in this paper. We assume that the reader is familiar with basic real analysis and elementary probability theory; we then introduce, in turn:
\begin{itemize}
    \item The notions of \emph{entropy}, \emph{mutual information}, and \emph{conditional mutual information} in both the discrete and continuous settings.
    \item The \emph{nonparametric} estimation of mutual information via the Kraskov–Stögbauer–Grassberger (KSG) $k$‐nearest‐neighbors (kNN) estimator.
    \item The concept of convergence in the norm $C^1(K)$ for functions defined on compact subsets $K\subset \mathbb{R}^n$.
    \item The theory of \emph{gradient flows} and ordinary differential equations (ODEs) of the form $\dot x(t) = -g(x(t))\,\nabla F(x(t))$, including existence, uniqueness, and basic stability estimates.
    \item Lipschitz continuity, differentiability classes ($C^k$), and regularity properties for functions on Euclidean spaces.
    \item Basic ideas from the theory of \emph{random fields} or \emph{stochastic processes indexed by space}, including covariance functions, stationarity, and concentration inequalities (in particular Hoeffding’s inequality).
    \item Notions from \emph{geometric measure theory} regarding compact domains with smooth boundary, volume (Lebesgue measure), and balls $\mathrm{Ball}(x;r)$ in $\mathbb{R}^n$.
\end{itemize}
Throughout, we adopt the following notational conventions:
\begin{itemize}
    \item $\mathbb{R}^n$ denotes \(n\)--dimensional Euclidean space, with the standard Euclidean norm $\|x\| = \sqrt{x_1^2 + \cdots + x_n^2}$.
    \item $\Omega \subset \mathbb{R}^n$ will denote a compact set with $C^2$ boundary, or more generally a domain (open connected set) whose closure $\overline{\Omega}$ is compact.
    \item Given a probability density $p(x)$ on $\mathbb{R}^n$, $H(p)$ denotes its (differential) entropy, and $I(X;Y)$ denotes mutual information between random variables $X,Y$ (possibly vector‐valued).
    \item For an open set $U\subset \mathbb{R}^n$, $C^k(U)$ is the space of $k$--times continuously differentiable real‐valued functions on $U$, and $\|f\|_{C^1(K)}$ denotes the $C^1$—norm on a compact $K\subset U$.
    \item For random variables indexed by points in space (a “random field”), we often write $\rho(x,\theta)$ where $\theta$ is a point in some probability space $(\Theta,\mathcal{F},\mathbb{P})$.
\end{itemize}

\subsection*{Entropy and Mutual Information}
\label{sec:entropy}
\subsubsection*{Discrete Entropy}
Let $X$ be a discrete random variable taking values in a finite or countable set $\mathcal{X}$, with probability mass function (pmf) $p_X(x) = \mathbb{P}(X=x)$. The \emph{Shannon entropy} of $X$ is
\[
H(X) \;=\; -\sum_{x\in\mathcal{X}} p_X(x)\,\ln p_X(x)\,,
\]
where throughout $\ln$ denotes the natural logarithm. Entropy $H(X)$ measures the expected “surprisal” of $X$ and satisfies $0 \le H(X) \le \ln|\mathcal{X}|$ when $|\mathcal{X}| < \infty$.

\subsubsection*{Differential Entropy}
When $X$ is a continuous random vector in $\mathbb{R}^d$ with probability density function (pdf) $p_X(x)$, its \emph{differential entropy} is defined as
\[
h(X) \;=\; -\int_{\mathbb{R}^d} p_X(x)\,\ln p_X(x)\,dx,
\]
provided the integral exists (i.e., $p_X$ is absolutely continuous and $\int p_X\,|\ln p_X| < \infty$). Unlike discrete entropy, differential entropy can be negative and is not invariant under change of variable.

\subsubsection*{Mutual Information}

Given two random variables (or vectors) \(X\) and \(Y\), with joint distribution \(p_{X,Y}(x,y)\) and marginals \(p_X(x)\), \(p_Y(y)\), the \emph{mutual information} between \(X\) and \(Y\) is defined by
\[
  I(X;Y) \;=\; \int_{\mathbb{R}^d \times \mathbb{R}^{d'}} 
    p_{X,Y}(x,y)\,\ln\!\Bigl(\frac{p_{X,Y}(x,y)}{\,p_X(x)\,p_Y(y)\,}\Bigr)\;dx\,dy
\]
in the continuous case, or the analogous sum in the discrete case. Equivalently, in the discrete setting:
\[
  I(X;Y) \;=\; H(X) \;+\; H(Y) \;-\; H(X,Y),
\]
and in the continuous setting:
\[
  I(X;Y) \;=\; h(X) \;+\; h(Y) \;-\; h(X,Y).
\]
Mutual information is always nonnegative, i.e.\ \(I(X;Y)\ge 0\), and vanishes precisely when \(X\) and \(Y\) are independent. It can also be written as the Kullback–Leibler divergence
\[
  I(X;Y) \;=\; D_{\mathrm{KL}}\bigl(p_{X,Y}\;\big\|\;p_X \otimes p_Y\bigr).
\]

\subsubsection*{Conditional Mutual Information}
For three random variables (vectors) $X$, $Y$, and $Z$, the \emph{conditional mutual information} of $X$ and $Y$ given $Z$ is
\[
I\bigl(X;Y \mid Z\bigr) 
\;=\;
\mathbb{E}_{Z}\Bigl[
D_{\mathrm{KL}}\bigl(p_{X,Y\mid Z}\,\big\|\,p_{X\mid Z}\otimes p_{Y\mid Z}\bigr)
\Bigr].
\]
Equivalently, in terms of (differential) entropies:
\[
I\bigl(X;Y \mid Z\bigr) 
\;=\; H(X \mid Z) + H(Y \mid Z) - H(X,Y \mid Z),
\]
or in the continuous case
\[
I\bigl(X;Y\mid Z\bigr) \;=\; h(X \mid Z) + h(Y \mid Z) - h(X,Y \mid Z).
\]
An equivalent formula in continuous form is
\[
I(X;Y \mid Z) 
= \int\int\int p_{X,Y,Z}(x,y,z)\,\ln \frac{p_{X,Y \mid Z}(x,y\,|\,z)}{\,p_{X\mid Z}(x\,|\,z)\,p_{Y\mid Z}(y\,|\,z)\,}\;dx\,dy\,dz.
\]
Conditional mutual information measures the residual statistical dependence between $X$ and $Y$ once $Z$ is known. In our context, $I$ (internal states), $B$ (blanket) and $E$ (external states) play the roles of $X$, $Z$, and $Y$ respectively.

\subsubsection*{Normalized “Blanket Strength”}
In the paper, the \emph{Markov blanket strength} is defined at a point $x$ by
\[
S(x) \;=\; 1 \;-\; \frac{\,I\bigl(I;E \,\mid\, B\bigr)\,}{\,I\bigl(I;E\bigr)}, 
\]
and the associated MB density by $\rho(x) = S(x)$. Here $I(I;E)$ and $I(I;E\mid B)$ denote the marginal and conditional mutual information restricted to the subsets $I(x)$, $B(x)$, and $E(x)$ around $x$. One must therefore be fluent in all of the foregoing definitions.

\subsection*{Nonparametric Estimation of Mutual Information via KSG--kNN}
\label{sec:ksg}

\subsubsection*{Nearest‐Neighbor Distances and Entropy Estimation}
Given a sample $\{\,z_i\,\}_{i=1}^N \subset \mathbb{R}^d$, consider the distance to the $k$‐th nearest neighbor:
\[
\varepsilon_k(i) \;=\; \min \bigl\{\,r>0:\,|\{\,j\neq i : \|z_j - z_i\| \le r\}| \ge k\,\bigr\}.
\]
The classical \emph{Kozachenko–Leonenko} (KL) estimator for the (differential) entropy $h(Z)$ is
\[
\hat h_{\mathrm{KL}}(Z) 
= \psi(N) - \psi(k) + \ln\bigl(c_d\bigr) + \frac{d}{N} \sum_{i=1}^N \ln \varepsilon_k(i),
\]
where $\psi(\cdot)$ is the digamma function, $c_d = \pi^{d/2}/\Gamma(\frac{d}{2}+1)$ is the volume of the unit ball in $\mathbb{R}^d$, and $\varepsilon_k(i)$ is half the distance to the $k$‐th nearest neighbor when using the maximum norm (or Euclidean norm if appropriate correction is made).

\subsubsection*{Kraskov–Stögbauer–Grassberger (KSG) Estimator}
Kraskov, Stögbauer, and Grassberger (2004) generalized the KL estimator to estimate mutual information between two continuous random vectors $X \in \mathbb{R}^{d_x}$ and $Y \in \mathbb{R}^{d_y}$. Given samples $\{(x_i,y_i)\}_{i=1}^N$, for each $i$ define
\[
\varepsilon_k(i) = \min\{\,\max\{\|x_j - x_i\|_\infty,\,\|y_j - y_i\|_\infty\}: 1 \le j \le N,\; j \neq i,\; \text{rank}(j) = k\,\},
\]
i.e.\ the distance (in the maximum norm) to the $k$‐th nearest neighbor in the joint space $\mathbb{R}^{d_x+d_y}$. Then count
\[
n_{x}(i) = \bigl|\{\,j \neq i : \|x_j - x_i\|_\infty \le \varepsilon_k(i)\}\bigr|,\quad
n_{y}(i) = \bigl|\{\,j \neq i : \|y_j - y_i\|_\infty \le \varepsilon_k(i)\}\bigr|.
\]
The KSG estimator for mutual information is
\[
\hat I_{\mathrm{KSG}}(X;Y)
\;=\; \psi(k) 
- \frac1k 
+ \psi(N)
- \frac{1}{N} \sum_{i=1}^N \bigl[\psi\bigl(n_{x}(i) + 1\bigr) + \psi\bigl(n_{y}(i) + 1\bigr)\bigr],
\]
where $\psi$ is again the digamma function. Under mild regularity conditions on the joint density $p_{X,Y}$, this estimator is (asymptotically) unbiased and consistent for large $N$. An analogous procedure can be applied to estimate conditional mutual information $I(X;Y \mid Z)$ by conditioning on $Z$ in a similar nearest‐neighbor scheme.

\subsubsection*{Convergence Properties and Conditions}
To employ KSG–kNN estimation within a theoretical analysis, one often needs more than mere pointwise consistency $\hat I \overset{p}{\longrightarrow} I_{\mathrm{true}}$. In the paper’s arguments, the key requirement is convergence in the norm
\[
\bigl\|\hat I(\cdot) - I_{\mathrm{true}}(\cdot)\bigr\|_{C^1(K)} \;=\; O_p\bigl(N^{-\alpha}\bigr),
\]
for some $\alpha>0$ and any compact $K$ in the domain. Convergence in $C^1(K)$ means:
\begin{enumerate}
    \item $\sup_{x\in K} |\hat I(x) - I_{\mathrm{true}}(x)| = O_p\bigl(N^{-\alpha}\bigr)$,
    \item $\sup_{x\in K} \bigl\|\nabla \hat I(x) - \nabla I_{\mathrm{true}}(x)\bigr\| = O_p\bigl(N^{-\alpha}\bigr)$,
\end{enumerate}
where $\nabla$ denotes the gradient with respect to the spatial coordinate $x\in\mathbb{R}^n$. Establishing such rates typically requires:
\begin{itemize}
    \item Assumptions that the true densities are bounded away from zero and infinity on $K$, with Lipschitz (or Hölder) continuous derivatives.
    \item Control of the bias and variance of the kNN–KSG estimator and uniformity over $x\in K$.
    \item Strong concentration inequalities for the nearest‐neighbor distances and counts $n_x(i)$, $n_y(i)$.
\end{itemize}

\subsection*{Convergence in the Norm \texorpdfstring{$C^1(K)$}{C1(K)}}
\label{sec:c1}

\subsubsection*{Function Spaces of Class \(C^1\)}
Let \(U \subset \mathbb{R}^n\) be an open set and \(K \subset U\) a compact subset. We say a function \(f:U \to \mathbb{R}\) belongs to \(C^1(U)\) if it is continuously differentiable, i.e., all first partial derivatives \(\partial f / \partial x_i\) exist and are continuous on \(U\). The restriction \(f|_K\) is then in \(C^1(K)\) in the sense that \(f\) and its gradient \(\nabla f\) are continuous on the compact set \(K\).  

\subsubsection*{Definition of the $C^1$--Norm}
For $f \in C^1(U)$ and a compact $K\subset U$, define
\[
\|f\|_{C^1(K)} 
\;=\; 
\sup_{x\in K} \bigl|f(x)\bigr| 
\;+\; 
\sup_{x\in K} \bigl\|\nabla f(x)\bigr\|.
\]
If $\|f - g\|_{C^1(K)} \to 0$ as some parameter (e.g., sample size $N$) grows, we say $f$ converges to $g$ in the $C^1(K)$ norm. This implies uniform convergence of both $f$ and $\nabla f$ on $K$.

\subsubsection*{Implications for Gradient‐Based Dynamics}
Convergence in $C^1(K)$ is crucial when one studies ODEs of the form
\[
\dot x(t) 
= -[\,1 - \rho_N(x(t))\,]\,\nabla F(x(t)),
\]
when $\rho_N(x) \to \rho_{\mathrm{true}}(x)$ in $C^1(K)$. Under such convergence, one can pass to the limit in the vector fields and deduce that solutions to the “estimated” flow approach those of the “true” flow, provided standard conditions of Lipschitz continuity hold. In particular, if $\rho_N\to\rho_{\mathrm{true}}$ and $\nabla\rho_N\to\nabla\rho_{\mathrm{true}}$ uniformly on $K$, then the direction of descent $-[1-\rho_N]\nabla F$ converges uniformly to $-[1-\rho_{\mathrm{true}}]\nabla F$. This is one of the stepping stones in the proof of Theorem~1.

\subsection*{Gradient Flows and Ordinary Differential Equations}
\label{sec:ode}

\subsubsection*{Gradient Descent in $\mathbb{R}^n$}
Given a continuously differentiable function $F:\Omega\subset\mathbb{R}^n \to \mathbb{R}$, the \emph{gradient flow} is the ODE
\[
\dot x(t) = -\nabla F\bigl(x(t)\bigr),
\]
with initial condition $x(0)=x_0\in\Omega$. Under the standard assumption that $\nabla F$ is globally Lipschitz (or at least locally Lipschitz on $\Omega$), the Picard–Lindelöf theorem guarantees the existence and uniqueness of a solution defined on a maximal interval. Moreover, if $\Omega$ is compact and $\nabla F$ is continuous, then the flow exists for all $t\ge 0$ and $F(x(t))$ is nonincreasing (since $\tfrac{d}{dt}F(x(t)) = \nabla F(x)\cdot \dot x = -\|\nabla F(x)\|^2 \le 0$).

\subsubsection*{Modified Gradient Flow with Mobility Function}
In the paper, the dynamics are modified as
\[
\dot x(t) = -M\bigl(x(t)\bigr)\,\nabla F\bigl(x(t)\bigr),
\]
where the \emph{mobility} (or “coupling”) function is
\[
M(x) = 1 - \rho(x), 
\quad 0 \le \rho(x)\le 1.
\]
Hence,
\[
\dot F\bigl(x(t)\bigr) 
\,=\, 
\nabla F(x)\cdot \dot x 
\,=\, 
- \bigl[1 - \rho(x)\bigr]\,\|\nabla F(x)\|^2 
\;\le\; 0.
\]
This shows that $F(x(t))$ is nonincreasing along trajectories. If $\rho(x)=1$ at some $x$, then $M(x)=0$ and $\dot x=0$, so the flow is \emph{frozen} at that point.

\subsubsection*{Existence and Uniqueness under Lipschitz Conditions}
Suppose $F\in C^2(\Omega)$, so $\nabla F$ is Lipschitz continuous on any compact $K\subset\Omega$ with Lipschitz constant $L_F$. If, in addition, $\rho(x)$ is $C^1$ on $K$, then $M(x) = 1 - \rho(x)$ is also Lipschitz on $K$. Consequently, the vector field $v(x) = -M(x)\,\nabla F(x)$ satisfies
\[
\|\,v(x) - v(y)\| 
\;=\; 
\bigl\|M(x)\,\nabla F(x) - M(y)\,\nabla F(y)\bigr\|
\;\le\; 
\bigl\|M(x)\,\bigl(\nabla F(x)-\nabla F(y)\bigr)\bigr\| 
+\|\,\nabla F(y)\|\;\bigl|M(x)-M(y)\bigr|.
\]
Since $M$ and $\nabla F$ are each bounded and Lipschitz on $K$, $v(x)$ is Lipschitz. Hence by the Picard–Lindelöf theorem, for each $x_0\in K$ there is a unique solution $x(t)\in K$ for some maximal interval of existence. If $K=\overline{\Omega}$ is compact and $v$ does not push trajectories outside $\overline{\Omega}$ (e.g., $v$ is tangent at the boundary), the solution exists for all $t\ge 0$ and remains in $\overline{\Omega}$.

\subsection*{Lipschitz Continuity and Differentiability Classes}
\label{sec:lipschitz}

\subsubsection*{$C^k$ Function Spaces}
Let $U\subset \mathbb{R}^n$ be open. We denote by $C^k(U)$ the set of functions $f:U\to\mathbb{R}$ whose partial derivatives up to order $k$ exist and are continuous on $U$. In particular:
\begin{itemize}
    \item $C^0(U)$ is the set of continuous functions.
    \item $C^1(U)$ consists of continuously differentiable functions; i.e., all first partials exist and are continuous.
    \item $C^2(U)$ consists of twice continuously differentiable functions, etc.
\end{itemize}
If $\Omega$ is compact with $C^2$ boundary, and $F\in C^2(\Omega)$, then $\nabla F$ is Lipschitz on $\Omega$ (since a continuously differentiable map on a compact set is automatically Lipschitz). Specifically, there exists $L_F>0$ such that
\[
\|\nabla F(x) - \nabla F(y)\| \;\le\; L_F \,\|x - y\|
\quad
\forall\,x,y\in \Omega.
\]

\subsubsection*{Lipschitz Continuity}
A function $f:K\to\mathbb{R}$ defined on a metric space $(K,d)$ is \emph{Lipschitz continuous} if there exists a constant $L\ge 0$ such that
\[
|f(x) - f(y)| \;\le\; L\,d(x,y)
\quad
\forall\,x,y \in K.
\]
If $f\in C^1(K)$ for a compact $K\subset\mathbb{R}^n$, then the mean value theorem implies $f$ is Lipschitz with Lipschitz constant
\[
L_f = \sup_{x\in K} \|\nabla f(x)\|.
\]
Analogously, a vector field $v:K\to\mathbb{R}^n$ is Lipschitz if $\sup_{x\in K}\|Dv(x)\|<\infty$, where $Dv(x)$ is the Jacobian matrix and $\|\cdot\|$ is the operator norm.

\subsection*{Random Fields and Concentration Inequalities}
\label{sec:randomfields}

\subsubsection*{Random Fields on a Compact Domain}
A \emph{random field} on a compact set $\Omega\subset\mathbb{R}^n$ is a collection of real‐valued random variables $\{\rho(x)\}_{x\in\Omega}$ defined on a common probability space $(\Theta,\mathcal{F},\mathbb{P})$. We denote $\rho(x,\theta)$ when emphasizing the dependence on the random element $\theta\in \Theta$. Conditions often imposed on $\rho(x,\theta)$ in the paper include:
\begin{itemize}
    \item \emph{Boundedness:} $0 \le \rho(x,\theta) \le 1$ for all $x,\theta$.
    \item \emph{Stationarity of mean:} $\mathbb{E}_\theta[\rho(x,\theta)] = \mu$ is constant for all $x\in\Omega$.
    \item \emph{Constant covariance with a deterministic field:} $\mathrm{Cov}(\rho(x),\,\|\nabla F(x)\|^2) = C$ is independent of $x$.
    \item \emph{Decay of spatial correlations:} There exists a length‐scale $\ell>0$ such that
    \[
    \bigl|\mathrm{Cov}\bigl(\rho(x),\,\rho(y)\bigr)\bigr| \;\le\; \sigma^2\exp\bigl(-\|x - y\|/\ell\bigr) 
    \quad \forall\,x,y\in\Omega.
    \]
\end{itemize}
The latter condition is a form of \emph{exponential mixing} or \emph{exponential decay of correlations} and ensures that values of $\rho$ at distant points become nearly independent.

\subsubsection*{Hoeffding’s Inequality for Bounded Random Variables}
Suppose $Z_1,\dots,Z_N$ are independent random variables with $a_i \le Z_i \le b_i$ almost surely. Then for any $\varepsilon>0$,
\[
\mathbb{P}\Bigl(\,\bigl|\tfrac{1}{N}\sum_{i=1}^N Z_i \;-\; \mathbb{E}[Z_i]\bigr|\ge \varepsilon\Bigr)
\;\le\; 
2\exp\!\Bigl(-\frac{2N^2\varepsilon^2}{\sum_{i=1}^N (b_i - a_i)^2}\Bigr).
\]
In the paper, to derive a \emph{uniform} high‐probability bound on 
\[
\varphi(x) = [1 - \rho(x)]\,\|\nabla F(x)\|^2
\]
over all $x\in\Omega$, one discretizes $\Omega$ by a finite grid $\{x^{(1)},\dots,x^{(N)}\}$ of mesh $\delta$. Then Hoeffding’s inequality yields, for each grid point $x^{(j)}$,
\[
\mathbb{P}\Bigl(\bigl|\varphi(x^{(j)}) - \mathbb{E}[\varphi(x^{(j)})]\bigr| \ge \varepsilon\Bigr)
\;\le\;
2\exp\bigl(-C\,\varepsilon^2\,\bigr)
\]
for some constant $C>0$ if $\varphi$ is bounded (since $0 \le \varphi \le \|\nabla F\|_\infty^2$). A union bound over all grid points (and then controlling the remainder of $\Omega$ by Lipschitz continuity) yields
\[
\mathbb{P}\Bigl(\sup_{x\in\Omega} \bigl|\varphi(x) - \mathbb{E}[\varphi(x)]\bigr| \ge \varepsilon\Bigr)
\;\le\;
N\,\cdot 2\exp\bigl(-C\,\varepsilon^2\bigr),
\]
so that with high probability the random field $\varphi(x)$ is uniformly close to its expectation.

\subsection*{Compact Domains and Volume in \texorpdfstring{\(\mathbb{R}^n\)}{R^n}}
\label{sec:geometry}

\subsubsection*{Compact Sets with Smooth Boundary}
Let \(\Omega \subset \mathbb{R}^n\) be a bounded open set whose boundary \(\partial\Omega\) is a \(C^2\) hypersurface. Such an \(\Omega\) is said to be a \emph{compact domain with \(C^2\) boundary} if \(\overline{\Omega}\) is compact and \(\partial\Omega\) is a \(C^2\) manifold. In particular:
\begin{itemize}
    \item There exist coordinate charts \((U_i,\psi_i)\) covering \(\partial\Omega\) such that \(\psi_i(U_i)\) is open in \(\mathbb{R}^{n-1}\) and \(\partial\Omega\) is locally given by \(x_n = \phi_i(x_1,\dots,x_{n-1})\) for some \(C^2\) function \(\phi_i\).  
    \item \(\Omega\) satisfies an \emph{interior sphere condition}: every point on \(\partial\Omega\) has a ball of positive radius contained in \(\Omega\) tangent to \(\partial\Omega\) at that point.
\end{itemize}
These properties guarantee that standard PDE and ODE results (e.g., existence of flows that remain in \(\Omega\) with vector fields tangent at the boundary) apply.

\subsubsection*{Volume of Balls}
The $n$‐dimensional Lebesgue measure (volume) of a ball of radius $r>0$ in $\mathbb{R}^n$ is
\[
\mathrm{Vol}\bigl(\mathrm{Ball}(x;r)\bigr) 
= \mathrm{Vol}\bigl(\mathrm{Ball}(0;r)\bigr) 
= c_n\,r^n,
\]
where 
\[
c_n = \frac{\pi^{n/2}}{\Gamma\bigl(\frac{n}{2}+1\bigr)}.
\]
In many consistency arguments for kNN estimators, one requires that $N\,\mathrm{Vol}(\mathrm{Ball}(x;r_2(N))) \to \infty$ as $N\to\infty$, which ensures that, on average, there are infinitely many sample points in an $r_2(N)$‐neighborhood of any given $x$. Usually $r_2(N)$ is chosen so that $N\,r_2(N)^n\to \infty$ but $r_2(N)\to0$.

\subsection*{Gradient Alignment and Monotonicity Conditions}
\label{sec:alignment}

\subsubsection*{Gradient Conditions for Theorem~1}
In Theorem~1, one assumes that there exist continuous functions
\[
I_{\mathrm{true}}\bigl(I(x);E(x)\bigr),\quad I_{\mathrm{true}}\bigl(I(x);E(x)\mid B(x)\bigr)
\;:\;D\subset\Omega \;\longrightarrow\; \mathbb{R},
\]
which are $C^1$ on an open set $D$, and satisfy
\[
