\begin{remark}
Note that (\ref{FAG channel}) can represent channels under an arbitrary number of interference sources. Channels under one interference source can be represented by having either $\mathcal{I}$ or $\mathcal{J}$ equal to $\{0\}$. For more than two interference sources, one can have 
\begin{equation}
    i_t = \sum_p i_t^p \text{\;,\;} j_t = \sum_q j_t^q \text{\;with\;} \mathcal{I} = \sum_p \mathcal{I}^p \text{\;and\;} \mathcal{J} = \sum_q \mathcal{J}^q,
\end{equation}
where, for arbitrary range of $p$ and $q$, $i_t^p$ and $j_t^q$ represents the elementary interference observations drawn from $\mathcal{I}^p$ and $\mathcal{J}^q$. We keep two interference sources rather than one because in the following we are interested in scenarios where the two interference sources are treated differently during decoding.
\end{remark}

\subsection{Encoding and Decoding}
We aim at reliably transmitting a message, $m$, over $n$  channel uses, where $m$ is drawn randomly and uniformly from $\{1,\;...\;,\;M\}$. The encoding scheme is given by a codebook $\mathcal{C}=\{\mathbf{x}^{(1)},\;...\;,\;\mathbf{x}^{(M)}\}\subset\mathcal{X}^n$, i.e., to transmit the message $m$, the corresponding codeword $\mathbf{x}^{(m)}$ is transmitted. We further assume i.i.d. random coding ensemble, hence
\begin{equation}\label{random_coding_ensemble}
    P_\mathbf{X}(\mathbf{x}^{(M)}) = \prod_{t=1}^{n} P_X(x_t^{(M)}),
\end{equation}
where $x_t^{(M)}$ is the $t$-th symbol of $\mathbf{x}^{(M)}$.

The decoder is represented by
\begin{equation}
    \hat{m} = \arg \max_{j=1,...,M} q^n(\mathbf{x}^{(j)},\;\mathbf{y}), \text{ with } q^n(\mathbf{x}^{(j)},\;\mathbf{y}) = \prod_{t=1}^n q(x^{(j)}_t,\;y_t),
\end{equation}
where $q(x,\;y)$ is a non-negative decoding metric.

For the FAGCI channel model described above, the optimal (matched) decoder maximizes the likelihood, which leads to the following optimal decoding metric:
\begin{equation}\label{matched decoding metric}
    q^\star(x,\;y) = \sum_{\Bar{i}\in\mathcal{I}} \sum_{\Bar{j}\in\mathcal{J}} \exp\left({-\frac{|y-\Bar{i}-\Bar{j}-x|^2}{\sigma_z^2}}\right).
\end{equation}

We are also interested in suboptimal (mismatched) but simpler decoding metrics. Primarily, the following two are considered:
\begin{enumerate}
    \item Partially treat interference as Gaussian RV by treating $I$ optimally and treating $J$ as a Gaussian RV:
    \begin{equation}\label{mismatched decoding metric partial}
    q(x,\;y) = \sum_{\Bar{i}\in\mathcal{I}} \exp\left({-\frac{|y-\Bar{i}-x|^2}{\sigma_j^2+\sigma_z^2}}\right).
    \end{equation}
    \item Fully treat interference as a Gaussian RV:
    \begin{equation}\label{mismatched decoding metric full}
    q(x,\;y) = \exp\left({-\frac{|y-x|^2}{\sigma_i^2+\sigma_j^2+\sigma_z^2}}\right).
    \end{equation}
\end{enumerate}
Indeed, if $J \sim \mathcal{CN}(0,\;\sigma_j^2)$ while $I$ remains to be from finite alphabet, (\ref{mismatched decoding metric partial}) is the optimal decoding metric for (\ref{FAG channel}); if $I \sim \mathcal{CN}(0,\;\sigma_i^2)$ and $J \sim \mathcal{CN}(0,\;\sigma_j^2)$, (\ref{mismatched decoding metric full}) is the optimal decoding metric. Note that (\ref{mismatched decoding metric full}) is a special case of (\ref{mismatched decoding metric partial}) as (\ref{mismatched decoding metric partial}) becomes (\ref{mismatched decoding metric full}) when viewing $i$ as $0$, and $j$ as $i+j$.

\subsection{Matched Capacity and a Lower Bound on Mismatched Capacity}
\begin{proposition}[Matched capacity]\label{matched capacity prop}
With optimal decoding, i.e., using (\ref{matched decoding metric}) as the decoding metric, the capacity of (\ref{FAG channel}) is given by the constellation-constrained MI as in (\ref{matched capacity}).
\end{proposition}
\begin{IEEEproof}
    See Appendix \ref{Appendix: Proof of matched capacity}.
\end{IEEEproof}

\begin{proposition}[A lower bound on mismatched capacity]\label{mismatched capacity prop}
With \textbf{any} suboptimal decoding metric denoted by $q(x,\;y)$, the mismatched capacity of (\ref{FAG channel}) is lower bounded by the GMI as in (\ref{mismatched capacity}), which is a function of $q(x,\;y)$. 
\end{proposition}
\begin{IEEEproof}
    See Appendix \ref{Appendix: Proof of mismatched capacity}.
\end{IEEEproof}

\begin{figure*}
\hrule
\begin{flalign}\label{matched capacity}
    I_{\text{MI}}(\mathcal{X},\;\mathcal{I},\;\mathcal{J},\;\sigma_z^2) = &\log|\mathcal{X}| - \frac{1}{|\mathcal{X}||\mathcal{I}||\mathcal{J}|}\sum_{x\in\mathcal{X}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}}\mathbb{E}_Z\left[\log\sum_{\Bar{x}\in\mathcal{X}}\sum_{\Bar{i}\in\mathcal{I}}\sum_{\Bar{j}\in\mathcal{J}}
    \exp
    \left({\frac{-|x+i+j+Z-\Bar{x}-\Bar{i}-\Bar{j}|^2}{\sigma_z^2}}\right)\right]&&\nonumber\\
    &+ \frac{1}{|\mathcal{I}||\mathcal{J}|}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}}\mathbb{E}_Z\left[\log\sum_{\Bar{i}\in\mathcal{I}}\sum_{\Bar{j}\in\mathcal{J}}\exp\left({\frac{-|i+j+Z-\Bar{i}-\Bar{j}|^2}{\sigma_z^2}}\right) \right]&&
\end{flalign}

\begin{flalign}\label{mismatched capacity}
    I_\text{GMI}(\mathcal{X},\;\mathcal{I},\;\mathcal{J},\;\sigma_z^2)
    =&\sup_{s\geq 0}\;\; \log|\mathcal{X}|-\frac{1}{|\mathcal{X}||\mathcal{I}||\mathcal{J}|} \sum_{x\in\mathcal{X}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}}\mathbb{E}_Z\left[ \log \sum_{\Bar{x}\in\mathcal{X}} q(\Bar{x},\;x+i+j+Z)^s \right]&&\nonumber\\
    &+ \frac{s}{|\mathcal{X}||\mathcal{I}||\mathcal{J}|} \sum_{x\in\mathcal{X}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}} \mathbb{E}_Z\left[ \log\; q(x,\;x+i+j+Z)  \right]&&
\end{flalign}

\begin{flalign}\label{mismatched capacity approx partial}
        I_\text{GMI,partial}^\text{approx.}(\mathcal{X},\;\mathcal{I},\;\mathcal{J},\;\sigma_z^2) 
        =& \log|\mathcal{X}| - \frac{1}{|\mathcal{X}||\mathcal{I}||\mathcal{J}|} \sum_{x\in\mathcal{X}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}} \log \sum_{\Bar{x}\in\mathcal{X}} \sum_{\Bar{i}\in\mathcal{I}} \exp\left(-\frac{|x+i+j-\Bar{x}-\Bar{i}|^2}{\sigma_j^2+2\sigma_z^2}\right)&&\nonumber\\
        &+ \frac{1}{|\mathcal{I}||\mathcal{J}|} \sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}} \log \sum_{\Bar{i}\in\mathcal{I}} \exp\left(-\frac{|i+j-\Bar{i}|^2}{\sigma_j^2+2\sigma_z^2}\right)&&
\end{flalign}

\begin{flalign}\label{mismatched capacity approx full}
        I_\text{GMI,full}^\text{approx.}(\mathcal{X},\;\mathcal{I},\;\mathcal{J},\;\sigma_z^2) 
        =& \log|\mathcal{X}| - \frac{1}{|\mathcal{X}||\mathcal{I}||\mathcal{J}|} \sum_{x\in\mathcal{X}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}} \log \sum_{\Bar{x}\in\mathcal{X}} \exp\left(-\frac{|x+i+j-\Bar{x}|^2}{\sigma_i^2+\sigma_j^2+2\sigma_z^2}\right) + \frac{1}{|\mathcal{I}||\mathcal{J}|} \sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{J}} \left(-\frac{|i+j|^2}{\sigma_i^2+\sigma_j^2+2\sigma_z^2}\right)&&
\end{flalign}
\hrule
\end{figure*}

\begin{remark}
    In (\ref{mismatched capacity}), the optimization over $s$ is convex \cite{Albert}.
\end{remark}

\begin{remark}
    The GMI given by (\ref{mismatched capacity}) is the highest achievable rate of (\ref{FAG channel}) under the assumption of i.i.d. random coding ensemble given by (\ref{random_coding_ensemble}). Breaking such assumption may lead to higher achievable rates, for example, by using constant-composition random coding ensemble\cite{Albert}.
\end{remark}

\begin{remark}
     In (\ref{mismatched capacity}), $I_\text{GMI}(\mathcal{X},\;\mathcal{I}+\mathcal{J},\;\{0\},\;Z)$ with $s=1$ and $q(x,\;y)$ from (\ref{mismatched decoding metric partial})  equals $I_{\text{MI}}(\mathcal{X},\;\mathcal{I},\;\mathcal{J},\;Z)$, as optimal decoding is a special case of mismatched decoding. 
\end{remark}

\subsection{Approximation of mismatched capacity}
One potential challenge of utilizing (\ref{mismatched capacity}) stems from the fact that it is difficult to compute the expectation term analytically. One may estimate (9) empirically at the cost of a high computational burden. For the sake of computation time, we provide a closed-form approximation of (\ref{mismatched capacity}). 

\begin{proposition}[Approximation of Mismatched Capacity]
    With $q(x,y)$ given by (\ref{mismatched decoding metric partial}) or (\ref{mismatched decoding metric full}), (\ref{mismatched capacity}) can be approximated by (\ref{mismatched capacity approx partial}) or (\ref{mismatched capacity approx full}) respectively.
\end{proposition}

\begin{IEEEproof}
    By setting $s=1$ and applying Jensen's inequality to both expectations in (\ref{mismatched capacity}), the expectations can be moved inside the $\log$ operators. With $q(x,\;y)$ given by (\ref{mismatched decoding metric partial}) or (\ref{mismatched decoding metric full}), the result is further simplified using Gaussian integral into (\ref{mismatched capacity approx partial}) or (\ref{mismatched capacity approx full}) respectively.
\end{IEEEproof}

\subsection{Results on GMI for FAGCI channels}
We first investigate the behavior of GMI and MI in the SISO FAGCI model as expressed by (\ref{FAG channel}) under different scenarios. In the following results, the two aforementioned mismatched decoding metrics are considered: 
\begin{itemize}
    \item Treating only $J$ as a Gaussian RV, as given by (\ref{mismatched decoding metric partial}): this is denoted by "GMI (partial)" in the following results.
    \item Treating both $I$ and $J$ as Gaussian RVs, as given by (\ref{mismatched decoding metric full}): this is denoted by "GMI (full)" in the following results.
\end{itemize}
We also plot the approximations of GMI, i.e., (\ref{mismatched capacity approx partial}) and (\ref{mismatched capacity approx full}), which is denoted as "GMI (partial) approx." and "GMI (full) approx." respectively. In the following, we assume that $x$ is generated using 16-QAM, while $i$ and $j$ are generated using QPSK. 

\begin{figure}
    \centering
    \includegraphics[width=6.5cm]{GMI_vs_MI_changing_X_pow_marked.eps}
    \caption{GMI and MI with $\sigma_i^2=20$dBm, $\sigma_j^2=10$dBm and $\sigma_z^2=0$dBm.}
    \label{Fig: GMI_vs_MI_varying_X_pow}
\end{figure}

In Figure \ref{Fig: GMI_vs_MI_varying_X_pow}, we consider a scenario with fixed interference and noise powers and characterize GMI and MI under different input power, i.e., $\sigma_x^2$. It can be observed that all the considered decoding metrics generally lead to improved achievable rates as the signal power increases, and all saturate at 4 bits at high input power, which is limited by the cardinality of 16-QAM. Hence, with very high input signal power, different decoding metrics under consideration lead to the same performance. With limited $\sigma_x^2$, it can be observed that "MI" upper-bounds "GMI (partial)", and "GMI (partial)" upper-bounds "GMI (full)". This aligns with expectations, because matched decoding uses optimal decoding metric, which utilizes full knowledge on interference. With mismatched decoding, only part of the interference knowledge is used. (\ref{mismatched decoding metric partial}) uses full knowledge on $I$ but only the variance of $J$ by approximating it as Gaussian RV. (\ref{mismatched decoding metric full}) uses only the variance of $I$ and $J$ by approximating both $I$ and $J$ as Gaussian RVs, hence uses even less knowledge on interference. In most cases, the more interference knowledge is utilized, the more accurate the decoding is. Hence, the order is almost always "MI" $\geq$ "GMI (partial)" $\geq$ "GMI (full)". Interestingly, MI does not increase monotonically as $\sigma_x^2$ grows but fluctuates. This is because, with finite constellations, the achievable rate also depends on the sum constellations, $\mathcal{X+I+J}$ and $\mathcal{I+J}$. Note that in (\ref{matched capacity}), the second and third terms are conditional entropy, $H(X,\;I,\;J|Y)$ and $H(I,\;J|Y,\;X)$, respectively. Such conditional entropy depends on the distinguishability of different points in the sum constellations. Since $\sigma_i^2$ and $\sigma_j^2$ are fixed, $H(I,\;J|Y,\;X)$ is unchanged (computed to be 0.0066 bits). The MI only depends on $H(X,\;I,\;J|Y)$, and therefore the sum constellation, $\mathcal{X+I+J}$. Figure \ref{Fig: sum constellation} visualizes $\mathcal{X+I+J}$ at the three marked points in Figure \ref{Fig: GMI_vs_MI_varying_X_pow}, with the corresponding $H(X,\;I,\;J|Y)$ and $I(X|Y)$ given in the captions. It can be observed that, in the three examples, as $\sigma_x^2$ increases, the sum constellation becomes less distinguishable, leading to increase in $H(X,\;I,\;J|Y)$, and therefore drop in $I(X|Y)$.
