	\section{Conclusion}
	In this paper, we proposed a regularized alternating method to solve MIPs. Instead of using cross-validation to find a proper regularization coefficient, we update its value iteratively. We have shown that our algorithm results in a sequence of improved solutions. Moreover, for the case that the objective function is continuously differentiable, we derived the convergence rate, a lower bound on the value of regularization coefficient, and an upper bound on the number of iterations required for the convergence. 


    \appendices
    \section{$\omega(\lambda)$ is increasing}\label{app:omega}	
    To show that function $\omega(\lambda)$ is increasing with respect to $\lambda$, first we need to show that $\mathcal{L}_{\lambda} (\mathbf{x},\mathbf{y},\mathbf{a})$ is an increasing function with respect to $\lambda$. According to the Cauchy-Schwarz inequality (Lemma 1), 
\begin{align*}
\left(n - \langle\mathbf{x},\mathbf{a}\rangle - \langle\mathbf{1}-\mathbf{x},\mathbf{1}-\mathbf{a}\rangle\right) \geq 0, \ \ \forall \mathbf{x},\mathbf{a}\in [0,1]^n.
\end{align*}
Let $\lambda_1 > \lambda_2 > 0$. Since
\begin{align*}
    \mathcal{L}_{\lambda} (\mathbf{x},\mathbf{y},\mathbf{a}) = f(\mathbf{x},\mathbf{y}) + \lambda \left(n - \langle\mathbf{x},\mathbf{a}\rangle - \langle\mathbf{1}-\mathbf{x},\mathbf{1}-\mathbf{a}\rangle\right),
\end{align*}
we can write 
\begin{align*}
    \mathcal{L}_{\lambda_1} (\mathbf{x},\mathbf{y},\mathbf{a})  \geq \mathcal{L}_{\lambda_2} (\mathbf{x},\mathbf{y},\mathbf{a}), \hspace{1cm} \forall (\mathbf{x},\mathbf{y},\mathbf{a}) \in \mathcal{R}.
\end{align*}
As a result, function $\mathcal{L}_{\lambda} (\mathbf{x},\mathbf{y},\mathbf{a})$ is increasing with respect to $\lambda$. According to the definition of $\omega(\lambda)$, we have 
\begin{align*}
    \omega(\lambda) := \underset{(\mathbf{x},\mathbf{y},\mathbf{a})\in \mathcal{R}}{\min} \ \mathcal{L}_{\lambda} (\mathbf{x},\mathbf{y},\mathbf{a}).
\end{align*}
Hence, we can write
\begin{align*}
    \omega(\lambda_1) = \underset{(\mathbf{x},\mathbf{y},\mathbf{a})\in \mathcal{R}}{\min} \ \mathcal{L}_{\lambda_1} (\mathbf{x},\mathbf{y},\mathbf{a}), \\
    \omega(\lambda_2) = \underset{(\mathbf{x},\mathbf{y},\mathbf{a})\in \mathcal{R}}{\min} \ \mathcal{L}_{\lambda_2} (\mathbf{x},\mathbf{y},\mathbf{a}).
\end{align*}
Since for any $(\mathbf{x},\mathbf{y},\mathbf{a}) \in \mathcal{R}$, we have $\mathcal{L}_{\lambda_1} (\mathbf{x},\mathbf{y},\mathbf{a})  \geq \mathcal{L}_{\lambda_2} (\mathbf{x},\mathbf{y},\mathbf{a})$,  We can apply the minimization operator to both sides as 
\begin{align*}
    \underset{(\mathbf{x},\mathbf{y},\mathbf{a})\in \mathcal{R}}{\min} \ \mathcal{L}_{\lambda_1} (\mathbf{x},\mathbf{y},\mathbf{a}) \geq \underset{(\mathbf{x},\mathbf{y},\mathbf{a})\in \mathcal{R}}{\min} \ \mathcal{L}_{\lambda_2} (\mathbf{x},\mathbf{y},\mathbf{a}).
\end{align*}
This results in 
\begin{align*}
    \omega(\lambda_1) \geq \omega(\lambda_2).
\end{align*}
Therefore, function $\omega(\lambda)$ is an increasing function of $\lambda$.


    \section{Trust region}\label{app:trust}	
    In what follows, we show that the feasible region of problem \eqref{eq:DC:original2} is a subset of the feasible region of the main problem, i.e., $\bar{\mathcal{D}}^{(l+1)} \subseteq \mathcal{D}, \forall l$. As a result, the solution of problem \eqref{eq:DC:original2}
 is feasible for the main problem in \eqref{eq:raw-problem}. 

\noindent The feasible region of the main problem is given in \eqref{feasiblereg}. Without loss of generality, we assume $p_{\text{nc}}$ number of the inequality constraints are non-convex and the remaining $p-p_{\text{nc}}$ constraints are all convex. Let $\mathcal{I}_{\text{nc}}$ and $\mathcal{I}_{\text{c}}$ denote the set of indices corresponding to the non-convex and convex constraints, respectively. We have $|\mathcal{I}_{\text{nc}}|=p_{\text{nc}}$ and $|\mathcal{I}_{\text{c}}|=p - p_{\text{nc}}$. For each $i \in \mathcal{I}_{\text{nc}}$, we can write $g_i(\mathbf{x},\mathbf{y}) = g_{i,a}(\mathbf{x},\mathbf{y}) - g_{i,b}(\mathbf{x},\mathbf{y})$, where $g_{i,a}(\mathbf{x},\mathbf{y})$ and $g_{i,b}(\mathbf{x},\mathbf{y})$ are convex functions with respect to $\mathbf{x}$ and $\mathbf{y}$. At the $(l+1)$-th iteration, the feasible region $\bar{\mathcal{D}}^{(l+1)}$ can be expressed as
\begin{align*}
    \bar{\mathcal{D}}^{(l+1)} =  \Big\{(\mathbf{x},\mathbf{y}) \Big| & g_i(\mathbf{x},\mathbf{y}) \leq 0, \  i \in \mathcal{I}_{\text{c}}, \\  & g_{i,a}(\mathbf{x},\mathbf{y}) - {\bar{g}}_{i,b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) \leq 0, \ i \in \mathcal{I}_{\text{nc}}, \\
	    &h_i(\mathbf{x},\mathbf{y}) = 0, \  i=1,2,\dots,q, \Big \},
\end{align*}
where ${\bar{g}}_{i,b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)})$ is the linearized version of ${g}^b_i(\mathbf{x},\mathbf{y})$. In the following lemma, we prove that $\bar{\mathcal{D}}^{(l+1)} \subseteq \mathcal{D}, \forall l$. 

\noindent \textbf{Lemma 5}. \textit{The feasible region of problem \eqref{eq:DC:original2}, i.e., $\bar{\mathcal{D}}^{(l+1)}$, is a subset of the feasible region of the main problem. In other words, $\bar{\mathcal{D}}^{(l+1)} \subseteq \mathcal{D}, \forall l$.}

\noindent \textit{Proof}. Let $(\mathbf{x},\mathbf{y}) \in \bar{\mathcal{D}}^{(l+1)}$. We have 
\begin{align*}
    & g_i(\mathbf{x},\mathbf{y}) \leq 0, \  i \in \mathcal{I}_{\text{c}}, \\  & g_{i,a}(\mathbf{x},\mathbf{y}) - {\bar{g}}_{i,b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) \leq 0, \ i \in \mathcal{I}_{\text{nc}}, \\
	    &h_i(\mathbf{x},\mathbf{y}) = 0, \  i=1,2,\dots,q.
\end{align*}
Since for each $i \in \mathcal{I}_{\text{nc}}$, $g_{i,b}(\mathbf{x},\mathbf{y})$ is a convex function, its linearized version is an under-estimator of $g_{i,b}(\mathbf{x},\mathbf{y})$. In other words, 
\begin{align*}
    {\bar{g}}_{i,b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) \leq g_{i,b}(\mathbf{x},\mathbf{y}), \ \ \  \forall (\mathbf{x},\mathbf{y}), \forall i \in \mathcal{I}_{\text{nc}}.
\end{align*}
As a result, 
\begin{align*}
    g_i(\mathbf{x},\mathbf{y}) & =  g_{i,a}(\mathbf{x},\mathbf{y}) - g_{i,b}(\mathbf{x},\mathbf{y}) \\
    & \leq g_{i,a}(\mathbf{x},\mathbf{y}) - {\bar{g}}_{i,b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) \leq 0, \ \ \ \forall i \in \mathcal{I}_{\text{nc}}.
\end{align*}
Hence, it is guaranteed to satisfy constraint $g_i(\mathbf{x},\mathbf{y}) \leq 0$, $\forall i \in \mathcal{I}_{\text{nc}}$. This means that $(\mathbf{x},\mathbf{y})$ satisfies all the following constraints as well
\begin{align*}
    & g_i(\mathbf{x},\mathbf{y}) \leq 0, \  i \in \mathcal{I}_{\text{c}}, \\  & g_i(\mathbf{x},\mathbf{y}) \leq 0, \  i \in \mathcal{I}_{\text{nc}}, \\
	    &h_i(\mathbf{x},\mathbf{y}) = 0, \  i=1,2,\dots,q.
\end{align*}
As a result, $(\mathbf{x},\mathbf{y}) \in \mathcal{D}$, and hence, $\bar{\mathcal{D}}^{(l+1)} \subseteq \mathcal{D}, \forall l$.
\hfill\(\blacksquare\) \\


\noindent The above lemma shows that any feasible solution of problem \eqref{eq:DC:original2} is also feasible for the main problem. As a result, we do not need to check the trust region.


    \section{Lipschitz continuity of linearized approximation}\label{app:LipDC}	
    From the definition of ${\bar{f}}_{b}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)})$ in equation (15) of the manuscript, for any $\mathbf{x}_1,\mathbf{x}_2 \in [0,1]^n$ we have
   \begin{align}
   \label{sag}
        &\left|\bar{f}^{(l+1)}(\mathbf{x}_1,\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) -\bar{f}^{(l+1)}(\mathbf{x}_2,\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)})\right| = \nonumber \\
        &\left| f_{a}(\mathbf{x}_1,\mathbf{y}) -  {\bar{f}}_{b}^{(l+1)}(\mathbf{x}_1,\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) -f_{a}(\mathbf{x}_2,\mathbf{y}) + {\bar{f}}_{b}^{(l+1)}(\mathbf{x}_2,\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)}) \right| = \nonumber\\
        &\left|f_{a}(\mathbf{x}_1,\mathbf{y}) - f_{a}(\mathbf{x}_2,\mathbf{y}) + \left\langle \nabla_{\mathbf{x}} f_{b} (\mathbf{x}^{(l)},\mathbf{y}^{(l)}), \mathbf{x}_2 - \mathbf{x}_1 \right\rangle \right| \labelrel\leq{ineq1} \nonumber \\
        &\left|f_{a}(\mathbf{x}_1,\mathbf{y}) - f_{a}(\mathbf{x}_2,\mathbf{y}) | + |\left\langle \nabla_{\mathbf{x}} f_{b} (\mathbf{x}^{(l)},\mathbf{y}^{(l)}), \mathbf{x}_2 - \mathbf{x}_1 \right\rangle \right| \labelrel\leq{ineq2} \nonumber\\
        &\left|f_{a}(\mathbf{x}_1,\mathbf{y}) - f_{a}(\mathbf{x}_2,\mathbf{y}) \right| + \left\| \nabla_{\mathbf{x}} f_{b} (\mathbf{x}^{(l)},\mathbf{y}^{(l)})\right\| \left\|\mathbf{x}_2 - \mathbf{x}_1 \right\|,
    \end{align}
    where inequality (a) holds due to the triangle inequality and inequality (b) results from the Cauchy-Schwarz inequality. Now, using the fact that 
    $f_{a}(\mathbf{x},\mathbf{y})$ is $L$-Lipschitz on $\mathbf{x} \in [0,1]^n$ and following the definition of Lipschitz continuity along with inequality \eqref{sag}, one can conclude that the Lipschitz constant of $\bar{f}^{(l+1)}(\mathbf{x},\mathbf{y}; \mathbf{x}^{(l)},\mathbf{y}^{(l)})$ on $\mathbf{x} \in [0,1]^n$ is $L + \left\| \nabla_{\mathbf{x}} f_{b} (\mathbf{x}^{(l)},\mathbf{y}^{(l)})\right\|$.




    \section{Choosing arbitrary ($\rho > 1$, $\lambda > 0$)}\label{app:arbit}	
Our algorithm includes two parameters, $\rho > 1$ and $\lambda > 0$, which need initialization. In what follows, we show that for any arbitrary choice of these parameters, our algorithm works. Hence, these parameters do not require cross-validation.



According to our update in Algorithm 1, the value of $\lambda$ at the $t$-th iteration is $\lambda^{(t)}=\rho ^ t \lambda^{(0)}$. This update guarantees at some iteration $t=T$, we have $\lambda^{(T)}=\rho ^ T \lambda^{(0)} > \lambda^\star$. In other words, the sufficient condition of Theorem 1 holds. As a result, the solution of $\mathbf{x}$ becomes binary. In the following lemma, we show that for any arbitrary choice of ($\rho > 1$,$\lambda^{(0)} >0$), there is a $t=T$ such that $\lambda^{(T)} > \lambda^\star$. 




\noindent \textbf{Lemma 6.} \textit{For any arbitrary ($\rho>1,\lambda^{(0)}>0$), there exist $T$ such that at iteration $t=T$, $\lambda^{(t)} > \lambda ^ \star$.}

\noindent \textit{Proof}. Depending on the initialization of $\lambda^{(0)}$, we have two cases:\\
\noindent 1) $\lambda^{(0)} > \lambda^{\star}$. In this case, at $T=1$ we have $\lambda^{(T)} > \lambda ^ \star$. 

\noindent 2) $\lambda^{(0)} \leq \lambda^{\star}$. In this case, if we select any $\rho > 1$, condition $\lambda^{(T)} > \lambda ^ \star$ is satisfied for $T = \ceil{ \frac{\log(\lambda^\star/\lambda^{(0)})}{\log \rho}}$, where $\ceil{.}$ is the ceiling operator.

\noindent Based on above arguments, the value of $T$ depends on the value of $\lambda ^ \star$ which is unknown. That is the reason we iteratively update $\lambda$ instead of choosing a fixed value.
\hfill\(\blacksquare\) \\

According to the above lemma, the choice of ($\rho>1,\lambda^{(0)}>0$) does not affect the final solution. Thus, there is no need to find their values via cross-validation. 

