\title{Exploiting Unstructured Sparsity in Fully Homomorphic Encrypted DNNs}


\author{Aidan Ferguson$^{1}$, Perry Gibson$^{1}$, Lara D'Agata$^{1}$, Parker McLeod$^{2}$, \\ 
